	["answers: mount | mounts | horse | wolf | ram | raptor | kodo | mechanostrider | nightsaber | skeletal horse"] = { "montura", "monturas", "caballo", "lobo", "carnero", "raptor", "kodo", "mecazancudo", "sable de la noche", "sable nocturno", "caballo esquelético", "caballo esqueletico" },
	["answers: murloc fin | murloc fins | fin | fins"] = { "aleta de múrloc", "aletas de múrloc", "aleta de murloc", "aletas de murloc", "aleta", "aletas" },
