	["arrows"] = "una flecha",
	["beats down hard at the air with both hands, one after the other, quickly."] = "golpea el aire con fuerza hacia abajo con ambas manos, una tras otra, rápido.",
	["blinks slowly and looks down at their boots with a puzzled frown."] = "parpadea despacio y se mira las botas, frunciendo el ceño sin entender.",
	["blinks twice, slowly, at the fire."] = "parpadea dos veces, despacio, mirando el fuego.",
	["blows gently across an open palm."] = "sopla suavemente sobre la palma abierta.",
	["bows their head and moves their lips silently, slowly, as if learning the words."] = "inclina la cabeza y mueve los labios sin voz, despacio, como quien se aprende las palabras.",
	["bows their head and rocks slowly where they sit, matching the pace of something very old."] = "baja la cabeza y se mece despacio en su lugar, al ritmo de algo muy viejo.",
	["bows their head for a moment with their eyes shut tight, then opens one of them."] = "inclina la cabeza un momento con los ojos bien cerrados, y luego abre uno.",
	["bows their head politely to the nearest log in the fire."] = "inclina la cabeza con cortesía ante el leño más cercano de la fogata.",
	["bows their head toward the fire."] = "inclina la cabeza hacia el fuego.",
	["bows their head with a small, rueful smile."] = "inclina la cabeza con una sonrisita apenada.",
	["bows their head."] = "inclina la cabeza.",
	["bows three times, very small, from where they sit."] = "hace tres reverencias, muy pequeñitas, sin levantarse.",
	["braces both hands against an invisible rail and looks sharply down."] = "se afianza con ambas manos en una baranda invisible y mira bruscamente hacia abajo.",
	["braces their shoulder against something heavy and shoves, teeth bared."] = "apoya el hombro contra algo pesado y empuja, enseñando los dientes.",
	["breaks an imaginary loaf in half and holds one piece out across the fire."] = "parte en dos un pan imaginario y tiende una mitad por encima del fuego.",
	["breaks off a crumb and sets it carefully on one knee, without looking."] = "parte una migaja y la pone con cuidado sobre una rodilla, sin mirar.",
	["breaks off and turns one long ear toward the dark, utterly still."] = "se interrumpe y gira una larga oreja hacia la oscuridad, sin moverse en absoluto.",
	["breaks off and turns their head very slowly, as if someone had spoken just behind them."] = "se interrumpe y gira la cabeza muy despacio, como si alguien le hubiera hablado justo detrás.",
	["breathes in the drifting woodsmoke and closes their eyes."] = "aspira el humo de leña que flota en el aire y cierra los ojos.",
	["breathes in the woodsmoke and, for a moment, seems to catch the smell of fresh bread instead."] = "respira el humo de la leña y, por un instante, parece oler pan recién hecho.",
	["brings a fist up to their mouth, then lowers it again without a sound."] = "se lleva el puño a la boca y luego lo baja otra vez sin hacer ruido.",
	["brings their hands together once, very softly, then lets them part."] = "junta las manos una sola vez, muy suave, y luego las separa.",
	["brushes one thumb in short, patient strokes across the palm of the other hand."] = "pasa un pulgar en trazos cortos y pacientes por la palma de la otra mano.",
	["brushes the air in front of them with the side of one hand, slowly, like a broom."] = "barre el aire frente a sí con el canto de la mano, despacio, como una escoba.",
	["brushes their own sleeve, then looks at their fingertips a moment too long."] = "se sacude la manga y luego se mira las yemas de los dedos un momento de más.",
	["but after the hunt, I take something away. What am I?"] = "pero tras la cacería me llevo algo de la presa. ¿Qué soy?",
	["but take one more hit, and I fall to the ground. What am I?"] = "pero si te pegan otra vez, caigo al suelo y me pierdes. ¿Qué soy?",
	["chews slowly and deliberately, eyes fixed on the dark beyond the firelight."] = "mastica despacio, con toda parsimonia, con la mirada fija en la oscuridad más allá de la luz del fuego.",
	["chuckles and pats their stomach."] = "se ríe entre dientes y se da unas palmaditas en la panza.",
	["chuckles low in their throat."] = "se ríe por lo bajo, desde la garganta.",
	["claps a hand to the top of their head, then slowly lowers it, finding nothing."] = "se lleva una mano a la coronilla y luego la baja despacio, sin encontrar nada.",
	["clasps their hands around an imagined rod and draws their shoulders back."] = "aprieta las manos alrededor de una caña imaginaria y echa los hombros hacia atrás.",
	["clears their throat and waits for the circle to go quiet."] = "carraspea y espera a que el círculo guarde silencio.",
	["clenches both fists tight, then throws them open."] = "aprieta los dos puños con fuerza y luego los abre de golpe.",
	["closes a fist around the washer, and the firelight goes out of it."] = "cierra el puño alrededor de la arandela, y la luz del fuego deja de brillar en ella.",
	["closes both hands around an invisible rim and lowers their eyes."] = "cierra ambas manos alrededor de un borde invisible y baja la mirada.",
	["closes one hand slowly into a fist."] = "cierra una mano despacio hasta formar un puño.",
	["closes the hand slowly and rests it on one knee."] = "cierra la mano despacio y la apoya en la rodilla.",
	["closes their eyes and nods slowly, keeping a beat that isn't there."] = "cierra los ojos y asiente despacio, siguiendo un ritmo que no está ahí.",
	["closes their eyes and sits quietly, as if a great field lay all around them."] = "cierra los ojos y se queda en silencio, como si un gran campo se extendiera a su alrededor.",
	["closes their eyes for a moment."] = "cierra los ojos un momento.",
	["closes their hands, slowly, around nothing."] = "cierra las manos despacio, sobre la nada.",
	["cocks their head to one side and blinks, first one eye and then the other."] = "ladea la cabeza y parpadea, primero con un ojo y luego con el otro.",
	["conjured water"] = "el agua mágica",
	["conjures a loaf, knocks on it, and winces at the sound."] = "conjura una hogaza, le da unos golpecitos y hace una mueca al oír cómo suena.",
	["copper ore"] = "la mena de cobre",
	["coughs politely into one fist, then glances nervously behind them."] = "tose con educación en el puño, y luego echa un vistazo nervioso hacia atrás.",
	["coughs, and becomes very interested in the fire."] = "tose, y de pronto se interesa muchísimo en el fuego.",
	["counts slowly on their fingers, and stops with one finger still raised."] = "cuenta despacio con los dedos, y se detiene con un dedo todavía levantado.",
	["counts the questions off on their fingers and runs out of fingers."] = "cuenta las preguntas con los dedos hasta que no le quedan dedos.",
	["counts the steps off on their fingers, then wrinkles their nose."] = "cuenta los pasos con los dedos y luego arruga la nariz.",
	["counts three points off on their fingers, then folds them away one by one."] = "cuenta tres puntos con los dedos y luego los va doblando uno por uno.",
	["cradles an invisible bowl in both hands, taking great care not to spill it."] = "sostiene un cuenco invisible con ambas manos, con muchísimo cuidado de no derramarlo.",
	["cradles something small in both hands and turns it over very carefully."] = "sostiene algo pequeño en ambas manos y le da vuelta con muchísimo cuidado.",
	["crumbles a heel of bread and lets it fall into the fire, one crumb at a time."] = "desmenuza un pedazo de pan y deja caer las migas al fuego, una por una.",
	["cups a hand as if holding something small and delicate."] = "ahueca una mano como si sostuviera algo pequeño y delicado.",
	["cups a hand over one ear and turns their face from the fire."] = "se cubre una oreja con la mano y aparta la cara del fuego.",
	["cups a hand to one ear, as if listening to a far-off hum."] = "se lleva una mano a la oreja, como si escuchara un zumbido lejano.",
	["cups a hand to their mouth and makes a sound like a dying goose."] = "se lleva la mano a la boca y hace un sonido como de ganso agonizando.",
	["cups an invisible flower in both hands, very carefully, as if it might fall apart."] = "sostiene una flor invisible entre las dos manos, con muchísimo cuidado, como si se fuera a deshacer.",
	["cups an invisible lantern in both hands and mouths something at it, frowning."] = "sostiene un farol invisible con las dos manos y le dice algo moviendo los labios, con el ceño fruncido.",
	["cups both hands together as if holding something small and damp."] = "junta las manos en forma de cuenco, como si sostuviera algo chiquito y húmedo.",
	["cups both hands together, as if holding something very small."] = "junta ambas manos en forma de cuenco, como si sostuviera algo muy pequeño.",
	["cups both hands together, then opens them slowly."] = "junta las manos formando un cuenco y luego las abre despacio.",
	["cups one hand behind an ear, looks left, then looks right with growing disbelief."] = "se pone una mano detrás de la oreja, mira a la izquierda y luego a la derecha, sin poder creerlo.",
	["cups one hand, as if holding something that might spill."] = "ahueca una mano, como si sostuviera algo que pudiera derramarse.",
	["cups their hands around their mouth and hoots softly."] = "ahueca las manos alrededor de la boca y ulula bajito.",
	["cups their hands gently, as though holding something small and warm."] = "ahueca las manos con delicadeza, como si sostuviera algo pequeño y tibio.",
	["curves one hand slowly through the air, as if guiding a growing branch."] = "traza despacio una curva en el aire con una mano, como si guiara una rama que crece.",
	["dabs their forehead and looks hopefully into an empty box."] = "se seca la frente a toquecitos y mira con esperanza dentro de una caja vacía.",
	["dangles a sock over the flames on a stick, feels it, and shakes their head."] = "cuelga un calcetín sobre las llamas en la punta de un palo, lo toca y niega con la cabeza.",
	["dips their head to an invisible rock with exaggerated courtesy, then again with real courtesy."] = "le hace una reverencia exagerada a una piedra invisible, y luego otra, esta vez de verdad.",
	["drags a heavy pack closer and gives it a thump."] = "acerca una mochila pesada y le da una palmada.",
	["drags a stick slowly through the ashes, clearing a line, and says nothing yet."] = "arrastra despacio un palito por la ceniza, abriendo una línea, y todavía no dice nada.",
	["draws a crooked line in the ashes with a stick, then tilts their head to read it upside down."] = "traza una línea chueca en la ceniza con un palito, y luego ladea la cabeza para leerla al revés.",
	["draws a faded blue ribbon from inside their sleeve and looks at it without speaking."] = "saca de la manga una cinta azul desteñida y la mira sin decir nada.",
	["draws a long breath and squares their shoulders, as though walking into a wind."] = "respira hondo y cuadra los hombros, como si entrara en un vendaval.",
	["draws a quick blade across the air and pulls one hand sharply free."] = "corta el aire con un cuchillo imaginario y libera una mano de un tirón.",
	["draws a slow circle in the air with one finger, and lets it fade."] = "dibuja en el aire un círculo lento con un dedo, y deja que se desvanezca.",
	["draws a slow line through the air with one finger."] = "traza una línea lenta en el aire con un dedo.",
	["draws a slow, grinning face in the air with one finger."] = "dibuja despacio en el aire, con un dedo, una cara sonriente.",
	["draws a straight line in the ashes with a stick, then slowly bends it into a curve."] = "traza una línea recta en la ceniza con un palito y luego la va doblando despacio hasta hacerla curva.",
	["draws an imaginary arrow, then pauses to count the rest with one finger."] = "saca una flecha imaginaria y se detiene a contar las demás con un dedo.",
	["draws an imaginary purse from their coat and weighs it thoughtfully in one palm."] = "saca una bolsa imaginaria del abrigo y la sopesa en una mano, con aire pensativo.",
	["draws back an invisible bowstring."] = "tensa una cuerda de arco invisible.",
	["draws back, takes a deep breath, and flings both arms wide."] = "se echa hacia atrás, respira hondo y abre los brazos de golpe.",
	["draws both hands in close, as if wrapping something tight around a pair of shoulders."] = "junta las dos manos hacia el pecho, como si envolviera algo con fuerza alrededor de unos hombros.",
	["draws five small circles in the ashes with a stick, spacing them out."] = "dibuja con un palito cinco circulitos en la ceniza, bien separados.",
	["draws one hand back and forth in slow, patient strokes."] = "mueve una mano de atrás hacia adelante en pasadas lentas y pacientes.",
	["draws one short line in the ashes with a stick and studies it."] = "traza una línea corta en la ceniza con un palito y se queda estudiándola.",
	["draws the coals closer with a short stick and watches the smaller glow."] = "junta las brasas con un palito y mira el resplandor, ahora más pequeño.",
	["draws their shoulders inward and holds utterly still."] = "encoge los hombros hacia dentro y se queda completamente inmóvil.",
	["draws up their knees, lowers their head, and breathes out slowly."] = "sube las rodillas, baja la cabeza y suelta el aire despacio.",
	["drops a splinter of wood into the coals and watches it go dark."] = "deja caer una astilla en las brasas y mira cómo se apaga.",
	["ducks sharply forward, one arm flung out behind them."] = "se agacha bruscamente hacia adelante, con un brazo extendido hacia atrás.",
	["ducks sharply, as though a stool just sailed over their head."] = "se agacha de golpe, como si un taburete le acabara de pasar volando por encima de la cabeza.",
	["dusts off their hands with great dignity."] = "se sacude las manos con gran dignidad.",
	["eases a fresh log onto the fire with great care, as one might tuck in something sleeping."] = "acomoda un leño nuevo en el fuego con muchísimo cuidado, como quien arropa a alguien que duerme.",
	["edges a little closer to the flames and rubs both arms."] = "se arrima un poco más a las llamas y se frota los brazos.",
	["edges back from the flames, tugs at their collar, and fans themselves furiously."] = "se aleja de las llamas, se jala el cuello de la ropa y se abanica con furia.",
	["fans out an invisible hand of cards and counts them twice."] = "abre en abanico unas cartas invisibles y las cuenta dos veces.",
	["fans out an invisible hand of cards and scowls at it."] = "abre en abanico una mano de cartas invisible y la mira con el ceño fruncido.",
	["fans their face with one hand."] = "se abanica la cara con una mano.",
	["fans their open mouth with one hand, eyes watering."] = "se abanica la boca abierta con una mano, con los ojos llorosos.",
	["feeds a thin stick to the flames and watches it catch."] = "le da al fuego una ramita delgada y mira cómo prende.",
	["feeds one more stick to the flames, unhurried, so the fire stands a little taller against the dark."] = "les echa una rama más a las llamas, sin prisa, y el fuego se alza un poco más contra la oscuridad.",
	["feeds the fire a larger stick, glaring at a spot near their knee."] = "le echa al fuego una rama más grande, fulminando con la mirada un punto junto a su rodilla.",
	["feeds the fire one more stick, though no one needs it, just in case."] = "le echa una vara más al fuego, aunque nadie la necesita, por si acaso.",
	["feels forward with one hand, slowly, as though blind."] = "tantea hacia adelante con una mano, despacio, como a ciegas.",
	["flexes one hand, as if still feeling the fight in it."] = "abre y cierra una mano, como si todavía sintiera la pelea en ella.",
	["flexes their off hand and looks at it as though it were an old friend."] = "flexiona la otra mano y la mira como a una vieja amiga.",
	["flicks an imaginary speck of ash from their sleeve."] = "se sacude de la manga una mota imaginaria de ceniza.",
	["flinches and wipes the side of their face."] = "se encoge y se limpia un lado de la cara.",
	["flinches as a log cracks and settles in the fire, then lays their hand back on their knee, one finger at a time."] = "se sobresalta cuando un leño cruje y se asienta en el fuego, y luego vuelve a apoyar la mano en la rodilla, un dedo a la vez.",
	["flinches back, as if from a sudden burst of shadow."] = "retrocede de golpe, como ante un estallido repentino de sombras.",
	["flinches from a popping spark and pats their singed eyebrows."] = "se aparta de una chispa que truena y se da palmaditas en las cejas chamuscadas.",
	["flinches hard to one side, throwing an arm over their head."] = "da un respingo hacia un lado y se cubre la cabeza con un brazo.",
	["flings a handful of dry grass on the fire and grins as it flares."] = "echa un puñado de pasto seco al fuego y sonríe cuando se aviva.",
	["flips a coin and catches it on the back of their hand."] = "lanza una moneda al aire y la atrapa en el dorso de la mano.",
	["flips an invisible coin and catches it on the back of one hand."] = "lanza una moneda invisible y la atrapa en el dorso de la mano.",
	["flutters their fingers downward like falling snow."] = "agita los dedos hacia abajo como nieve que cae.",
	["folds an invisible scrap of paper small, then tucks it low with one finger."] = "dobla chiquito un papelito invisible, y luego lo mete abajo con un dedo.",
	["folds an invisible sheet of paper in half, then in half again."] = "dobla una hoja de papel invisible a la mitad, y luego otra vez a la mitad.",
	["folds one hand carefully over the other, as if tying the corners of a cloth."] = "dobla una mano sobre la otra con cuidado, como si anudara las puntas de un trapo.",
	["folds their arms and frowns down at an imaginary traveler."] = "se cruza de brazos y mira con el ceño fruncido a un viajero imaginario.",
	["folds their arms and stares into the fire with tremendous patience."] = "se cruza de brazos y mira el fuego con una paciencia tremenda.",
	["folds their hands and nods with immense, unhurried gravity."] = "entrelaza las manos y asiente con una gravedad inmensa y sin ninguna prisa.",
	["folds their hands and puts on a face of enormous patience."] = "junta las manos y pone cara de una paciencia infinita.",
	["folds their hands in their lap."] = "junta las manos sobre el regazo.",
	["follows one spark up until it goes out, and looks back down without a word."] = "sigue con la vista una chispa hasta que se apaga, y vuelve a bajar la mirada sin decir palabra.",
	["frames a small square in the air with their fingers, and peers through it."] = "enmarca un cuadrito en el aire con los dedos y se asoma a través de él.",
	["free for the thirsty who wander about. What am I?"] = "y no le cobra ni un cobre al que anda sediento. ¿Qué soy?",
	["freezes mid-motion, eyes sliding toward the ground."] = "se paraliza a medio movimiento, con la mirada deslizándose hacia el suelo.",
	["furrows their brow and thinks very slowly, tapping a finger on their chin."] = "frunce el ceño y piensa muy despacio, dándose golpecitos en la barbilla con un dedo.",
	["gathers a few twigs and lays them neatly at the edge of the fire."] = "junta unas ramitas y las acomoda con cuidado al borde del fuego.",
	["gathers the invisible cards together and holds them against their chest."] = "junta las cartas invisibles y las aprieta contra el pecho.",
	["gazes down at their open hands as if weighing something."] = "baja la mirada a sus manos abiertas, como si sopesara algo.",
	["gazes into the flames, giving the question time to settle."] = "mira fijamente las llamas, dándole tiempo a la pregunta para que se asiente.",
	["gazes off into the distance with great dignity."] = "mira a lo lejos con gran dignidad.",
	["gazes solemnly into the distance, nodding, then looks down and sighs."] = "mira a lo lejos con solemnidad, asintiendo, y luego baja la vista y suspira.",
	["gazes through the heat shimmer above the fire, as though something blue might lie on the other side."] = "mira a través del aire que vibra de calor sobre el fuego, como si del otro lado hubiera algo azul.",
	["gives a satisfied nod and brushes their palms together."] = "asiente con satisfacción y se sacude las palmas.",
	["gives a small, knowing smile."] = "esboza una sonrisita cómplice.",
	["gives the burning log in the fire a long, respectful look."] = "le dedica al leño que arde en la fogata una mirada larga y respetuosa.",
	["gives the fire a small, apologetic nod, just in case."] = "le hace al fuego un pequeño gesto de disculpa con la cabeza, por si acaso.",
	["gives {target} a good long look, then slides an invisible heel of bread across to them."] = "se queda mirando bien a {target} un buen rato, y luego le desliza un trozo de pan invisible.",
	["glances at the empty space beside them, and shifts over a little."] = "mira el espacio vacío a su lado y se mueve un poquito para hacer lugar.",
	["glances at the empty space beside them, then leans in a little closer to the fire."] = "mira el espacio vacío a su lado, y luego se acerca un poco más al fuego.",
	["glances at the flames, and for a moment does not seem certain what color they are."] = "mira las llamas, y por un momento no parece tener claro de qué color son.",
	["glances at the sky, as if checking the hour."] = "mira al cielo, como para calcular la hora.",
	["glances at their own shadow in the firelight, checking which way it falls."] = "mira su propia sombra a la luz del fuego, para ver hacia dónde cae.",
	["glances at {target}, then away, then back again."] = "mira a {target}, luego aparta la vista, y luego vuelve a mirar.",
	["glances back at their own shadow, stretched long behind them, and does not look for long."] = "mira de reojo su propia sombra, alargada a sus espaldas, y no la mira por mucho rato.",
	["glances down at about knee height and gives a long-suffering sigh."] = "mira hacia abajo, más o menos a la altura de la rodilla, y suelta un suspiro de mártir.",
	["glances down at the campfire beside them and, very casually, shifts over a little."] = "mira de reojo la fogata que tiene al lado y, como quien no quiere la cosa, se hace un poquito a un lado.",
	["glances left, then right, then leans closer."] = "mira a la izquierda, luego a la derecha, y se inclina un poco más.",
	["glances off toward the trees."] = "echa una mirada hacia los árboles.",
	["glances out at the dark beyond the firelight, then back at the circle."] = "echa un vistazo a la oscuridad más allá del fuego y luego vuelve a mirar al círculo.",
	["glances out past the firelight, as if checking something."] = "echa un vistazo más allá de la luz del fuego, como si revisara algo.",
	["glances out past the firelight, toward the dark between the trees."] = "echa un vistazo más allá de la luz del fuego, hacia la oscuridad entre los árboles.",
	["glances over at {target} and tips their head."] = "mira a {target} y le hace un saludo con la cabeza.",
	["glances over one shoulder, then back again."] = "echa un vistazo por encima del hombro, y luego vuelve la vista al frente.",
	["glances over one shoulder, then laughs a little too loudly."] = "mira por encima del hombro y luego se ríe un poquito demasiado fuerte.",
	["glances over one shoulder, then mimes sliding something carefully back onto a high shelf."] = "mira por encima del hombro y luego hace como que devuelve algo, con mucho cuidado, a una repisa alta.",
	["glances over one shoulder, then pretends they didn't."] = "mira por encima del hombro y luego finge que no lo hizo.",
	["glances over one shoulder, then turns back to the fire a little too quickly."] = "echa un vistazo por encima del hombro y luego se voltea hacia el fuego un poco demasiado rápido.",
	["glances past the firelight and counts something out there under their breath."] = "mira más allá de la luz del fuego y cuenta algo allá afuera entre dientes.",
	["glances past {target} into the dark, and holds very still for a moment."] = "mira más allá de {target}, hacia la oscuridad, y no mueve ni un músculo por un momento.",
	["glances sideways at the empty space next to them, as if keeping pace with it."] = "mira de reojo el espacio vacío a su lado, como si le siguiera el paso.",
	["glances skyward out of habit."] = "mira al cielo por costumbre.",
	["glances up at the branches overhead, as though one of them might move."] = "mira hacia las ramas de arriba, como si alguna se fuera a mover.",
	["glances up past the reach of the firelight, as if counting something overhead."] = "alza la vista más allá de la luz del fuego, como si contara algo allá en lo alto.",
	["glances up, as if at a high window, and flinches."] = "alza la mirada, como hacia una ventana alta, y se encoge.",
	["goes completely still for a long moment, barely breathing."] = "se queda completamente inmóvil un largo rato, apenas respirando.",
	["goes completely still, one hand flat at their side, eyes fixed on nothing."] = "se queda completamente inmóvil, con una mano plana a un costado y la mirada fija en la nada.",
	["goes quiet and lowers their eyes to the flames."] = "guarda silencio y baja la mirada a las llamas.",
	["goes quiet, letting the crackle of the fire fill the place where the answer would be."] = "se queda en silencio y deja que el crepitar del fuego llene el lugar donde iría la respuesta.",
	["goes very still, and looks down at their empty hands."] = "se queda sin moverse y baja la mirada a sus manos vacías.",
	["grabs at something over their shoulder and leans back with all their weight."] = "agarra algo por encima del hombro y se echa hacia atrás con todo su peso.",
	["grabs at the air with both hands, then wrenches them sharply to one side."] = "agarra el aire con ambas manos y luego da un tirón brusco hacia un lado.",
	["grins across the fire."] = "sonríe de oreja a oreja por encima del fuego.",
	["grins and takes a long, satisfied drink."] = "sonríe y da un trago largo, con satisfacción.",
	["grins wide, showing every tooth, and holds it a little too long."] = "sonríe de oreja a oreja, enseñando todos los dientes, y sostiene la sonrisa un poco más de la cuenta.",
	["grins, then hides the grin behind one hand."] = "sonríe, y luego esconde la sonrisa detrás de una mano.",
	["grips an imaginary set of levers and jerks them left and right."] = "se aferra a unas palancas imaginarias y las mueve a tirones, a la izquierda y a la derecha.",
	["grips an imagined club and gives one short, checked swing above their knee."] = "empuña un garrote imaginario y da un solo golpe corto y contenido por encima de la rodilla.",
	["grips an invisible rope in both fists, and leans back hard."] = "aprieta una cuerda invisible con los dos puños y se echa hacia atrás con fuerza.",
	["grips an invisible sack by the neck and swings it round in a wide, low arc."] = "agarra un costal invisible por el cuello y lo hace girar en un arco amplio y bajo.",
	["grips an invisible staff that keeps trying to tilt to one side, and wrestles it upright."] = "agarra un bastón invisible que insiste en inclinarse hacia un lado, y forcejea para enderezarlo.",
	["grips an invisible totem in both hands and drives it into the ground beside them."] = "aprieta un tótem invisible con las dos manos y lo clava en el suelo a su lado.",
	["grips reins and leans sharply to one side, cheeks puffed."] = "aprieta unas riendas y se inclina bruscamente hacia un lado, con los cachetes inflados.",
	["grunts, a smile tugging at one tusk."] = "gruñe, con media sonrisa asomando junto a un colmillo.",
	["gurgles deep in their throat, then wipes their chin with great dignity."] = "gorgotea desde el fondo de la garganta y luego se limpia la barbilla con gran dignidad.",
	["hauls hand over hand on an invisible rope, leaning back."] = "jala una cuerda invisible mano tras mano, echándose hacia atrás.",
	["hefts an invisible, very heavy volume in both hands and squares up."] = "sopesa con las dos manos un tomo invisible y pesadísimo, y se planta firme.",
	["holds a flat hand low, then lets it slowly rise and sway."] = "mantiene una mano plana muy abajo y luego la deja subir despacio, meciéndose.",
	["holds a hand out over the coals, palm down, and slowly draws it back."] = "extiende una mano sobre las brasas, con la palma hacia abajo, y la retira despacio.",
	["holds an invisible crate out at arm's length and leans their head away from it."] = "sostiene una caja invisible con los brazos estirados y aparta la cabeza de ella.",
	["holds an invisible drawing out at arm's length and tilts their head at it."] = "sostiene un dibujo invisible con el brazo estirado y ladea la cabeza al mirarlo.",
	["holds an invisible umbrella high overhead and squints up at it."] = "sostiene una sombrilla invisible en alto y la mira entrecerrando los ojos.",
	["holds an invisible vial up to the light."] = "alza un frasquito invisible hacia la luz.",
	["holds both arms out wide and lets them sink slowly, counting with small nods."] = "abre los brazos y los deja bajar despacio, llevando la cuenta con la cabeza.",
	["holds both hands close together above the warmth."] = "junta las dos manos sobre el calor.",
	["holds both hands out toward the flames."] = "extiende las dos manos hacia las llamas.",
	["holds both palms out toward the fire, as if feeling warmth from something unseen."] = "extiende las dos palmas hacia el fuego, como si sintiera el calor de algo invisible.",
	["holds both palms toward the fire for a long moment, as if checking that they still feel it."] = "acerca ambas palmas al fuego un largo rato, como para comprobar que todavía lo sienten.",
	["holds one boot out toward the flames and regards it with long-suffering sadness."] = "extiende una bota hacia las llamas y la contempla con una tristeza resignada.",
	["holds one elbow up to the firelight and studies it for a long moment."] = "levanta un codo hacia la luz del fuego y lo examina un largo rato.",
	["holds one finger very still above an open palm, waiting."] = "mantiene un dedo muy quieto sobre la palma abierta, esperando.",
	["holds one forearm close against their chest, and reaches carefully up with the other."] = "pega un antebrazo contra el pecho y estira el otro hacia arriba con cuidado.",
	["holds one hand flat above their head and squints up from beneath it."] = "se pone una mano plana sobre la cabeza y entrecierra los ojos mirando hacia arriba.",
	["holds one hand halfway raised, eyes moving slowly left and right."] = "mantiene una mano a medio levantar, con los ojos moviéndose despacio de izquierda a derecha.",
	["holds one hand out to the fire, the other still on the pouch, and seems unsure which is warmer."] = "acerca una mano al fuego, con la otra todavía en la bolsita, y parece no saber cuál está más tibia.",
	["holds one open palm out toward the fire, as if to have it read."] = "tiende la palma abierta hacia el fuego, como para que se la lean.",
	["holds out a cupped hand and drops invisible nails into it, one at a time."] = "extiende una mano ahuecada y deja caer en ella clavos invisibles, uno por uno.",
	["holds out a cupped hand, then slowly pushes it away."] = "extiende una mano ahuecada, y luego la aparta despacio.",
	["holds out a hand, as if feeling for a breeze."] = "extiende una mano, como si buscara una brisa.",
	["holds out an empty palm toward the fire, hopefully."] = "tiende la palma vacía hacia el fuego, por si acaso.",
	["holds out an invisible pen across the fire toward {target}."] = "le tiende a {target} una pluma invisible por encima del fuego.",
	["holds out an invisible spoon toward {target} with both hands, like a knight offering a sword."] = "le ofrece a {target} un cucharón invisible con las dos manos, como un caballero que ofrece su espada.",
	["holds out both hands and accepts something small, with visible surprise."] = "extiende ambas manos y recibe algo pequeño, con sorpresa evidente.",
	["holds out both hands and regards them quietly."] = "extiende las dos manos y las contempla en silencio.",
	["holds out both hands as if warming a coat before a fire, turning it slowly."] = "extiende ambas manos como si calentara un abrigo frente al fuego, y lo gira despacio.",
	["holds out cupped hands toward {target}, as if passing a bowl across the fire."] = "le tiende las manos ahuecadas a {target}, como si le pasara un tazón por encima del fuego.",
	["holds out cupped hands, very still."] = "extiende las manos ahuecadas, sin moverlas ni un poquito.",
	["holds out one arm and scratches the air gently with the other hand."] = "extiende un brazo y con la otra mano rasca el aire, con suavidad.",
	["holds out one arm, very still, and looks along it."] = "extiende un brazo, sin moverlo para nada, y lo recorre con la mirada hasta la punta de los dedos.",
	["holds out one hand as if guiding someone frail across a road."] = "extiende una mano como si guiara a alguien frágil al cruzar un camino.",
	["holds out one open palm and watches it closely."] = "extiende la palma abierta y la observa con atención.",
	["holds still, then glances toward their own shadow and quickly back to the fire."] = "se queda inmóvil, luego echa un vistazo a su propia sombra y regresa la mirada al fuego, rápido.",
	["holds the back of one hand up to the firelight so an old scar shows, and looks at it for a while."] = "alza el dorso de una mano hacia la luz del fuego para que se vea una cicatriz vieja, y la mira un rato.",
	["holds the letter a moment too near the flames, then folds it carefully and tucks it away again."] = "sostiene la carta un instante demasiado cerca de las llamas, luego la dobla con cuidado y la vuelve a guardar.",
	["holds their hands apart as though measuring a very fine pair of boots."] = "separa las manos como si midiera un par de botas finísimas.",
	["holds their hands close to the flames, turns them over, and regards them in silence."] = "acerca las manos a las llamas, las voltea y las contempla en silencio.",
	["holds their palms out to the flames and nods toward {target}'s side of the fire."] = "extiende las palmas hacia las llamas y señala con la cabeza el lado del fuego donde está {target}.",
	["holds two fingers very still, then twitches them a hair to one side, timing something."] = "mantiene dos dedos muy quietos y luego los mueve apenas hacia un lado, calculando algo.",
	["holds two invisible halves apart and looks from one to the other."] = "sostiene dos mitades invisibles separadas y mira de una a otra.",
	["holds up a hand and counts along their fingers, then starts on the other hand."] = "alza una mano y va contando con los dedos, y luego sigue con la otra mano.",
	["holds up a hand with the thumb and finger a few inches apart, and smiles."] = "levanta una mano con el pulgar y el índice un poco separados, y sonríe.",
	["holds up a small steel washer between finger and thumb."] = "sostiene una pequeña arandela de acero entre el índice y el pulgar.",
	["holds up a thumb and finger, pinching something thin and small."] = "levanta el pulgar y el índice, como pellizcando algo delgado y pequeño.",
	["holds up a thumb and forefinger, barely apart."] = "levanta el pulgar y el índice, casi juntos.",
	["holds up a thumb and squints along it, measuring someone from a distance."] = "levanta un pulgar, cierra un ojo y mide a alguien a la distancia.",
	["holds up a tiny invisible stone and squints at it."] = "levanta una piedrita invisible y la mira con los ojos entrecerrados.",
	["holds up an imaginary blade, squints along it, and grimaces."] = "sostiene una hoja imaginaria, mira a lo largo del filo entrecerrando los ojos, y hace una mueca.",
	["holds up an invisible carving and turns it around, frowning, trying another angle."] = "sostiene una talla invisible y le da vueltas, con el ceño fruncido, probando otro ángulo.",
	["holds up an invisible scrap between two fingers."] = "sostiene un trapito invisible entre dos dedos.",
	["holds up an invisible vial and squints at it against the firelight."] = "sostiene un frasco invisible y lo examina contra la luz del fuego, entrecerrando los ojos.",
	["holds up an invisible waterskin and shakes it, listening closely."] = "levanta un odre invisible y lo sacude, escuchando con atención.",
	["holds up one finger and lets the question hang in the smoke."] = "levanta un dedo y deja que la pregunta flote en el humo.",
	["holds up one finger, as if the worst part is coming."] = "alza un dedo, como si ahora viniera lo peor.",
	["holds up one finger, thinks better of it, and opens both hands."] = "levanta un dedo, lo piensa mejor y abre las dos manos.",
	["holds up one hand and slowly closes it into a loose fist, not a tight one."] = "alza una mano y la cierra despacio en un puño flojo, no apretado.",
	["holds up one hand as though steadying a lamp, and keeps it very still."] = "levanta una mano como si sostuviera una lámpara, y la mantiene muy quieta.",
	["holds up one hand with the fingers spread, studying it as though it belonged to someone else."] = "alza una mano con los dedos abiertos y la estudia como si fuera de otra persona.",
	["holds up something small between finger and thumb, turning it so the firelight slides along it."] = "sostiene algo pequeño entre el índice y el pulgar, y lo gira para que la luz del fuego se deslice por él.",
	["holds up three fingers, then folds them down, one at a time."] = "levanta tres dedos y luego los dobla, uno por uno.",
	["holds up two empty fists and stares at them in remembered horror."] = "levanta dos puños vacíos y los mira con el horror del recuerdo.",
	["holds up two fingers, side by side, and gazes at them fondly."] = "alza dos dedos, uno junto al otro, y los mira con cariño.",
	["holds up two fingers, then knocks them together."] = "levanta dos dedos y los choca entre sí.",
	["holds up two fingers, then slowly lowers one of them."] = "levanta dos dedos y luego baja uno, muy despacio.",
	["hums a few bars of an old marching song."] = "tararea unos compases de una vieja marcha militar.",
	["hums a few wandering notes that never quite settle into a song."] = "tararea unas notas sueltas que nunca terminan de volverse canción.",
	["hums the last notes again, more softly."] = "vuelve a tararear las últimas notas, más bajito.",
	["hunches low and leans slowly forward, inch by inch."] = "se agazapa y se inclina hacia adelante despacio, palmo a palmo.",
	["hunches low and moves their hands slowly, as if sneaking."] = "se encorva y mueve las manos despacio, como a hurtadillas.",
	["hunches low, gripping the air on either side and refusing to look down."] = "se agacha, aferrándose al aire a ambos lados y negándose a mirar hacia abajo.",
	["hunches low, grips an invisible rim, and leans hard into a turn."] = "se agacha, se aferra a un borde invisible y se inclina con fuerza en una curva.",
	["hunches low, one hand out for balance, and glances back with wide eyes."] = "se agacha, con una mano extendida para mantener el equilibrio, y mira hacia atrás con los ojos muy abiertos.",
	["hunches their shoulders and bares their teeth, growling softly."] = "encorva los hombros y enseña los dientes, gruñendo bajito.",
	["is quiet for a moment, then nods slowly."] = "guarda silencio un momento y luego asiente despacio.",
	["is quiet for a moment, watching the coals."] = "se queda en silencio un momento, mirando las brasas.",
	["is quiet for a moment."] = "guarda silencio un momento.",
	["jabs a thumb over one shoulder, toward some ridge in the dark."] = "señala con el pulgar por encima del hombro, hacia alguna cresta en la oscuridad.",
	["jerks forward suddenly, one arm wrenched out straight, teeth bared."] = "se va de golpe hacia adelante, como si le jalaran un brazo, enseñando los dientes.",
	["jerks one fist forward, then draws back an imagined blade with the other hand."] = "lanza un puño hacia adelante y con la otra mano retira una hoja imaginaria.",
	["keeps their eyes on the flames, as if still holding that light up for someone."] = "no aparta los ojos de las llamas, como si todavía sostuviera esa luz para alguien.",
	["keeps their gaze fixed on the ground as they speak."] = "mantiene la mirada fija en el suelo mientras habla.",
	["knocks twice on the ground beside them."] = "golpea dos veces el suelo con los nudillos.",
	["laughs quietly into one hand."] = "se ríe bajito, tapándose la boca con la mano.",
	["lays an invisible flower down beside them, very carefully."] = "deja una flor invisible a su lado, con muchísimo cuidado.",
	["lays one hand flat on the ground, then the other beside it."] = "apoya una mano abierta en el suelo, y luego la otra a su lado.",
	["lays one hand flat, then sets the other on top of it, very carefully."] = "pone una mano plana y luego coloca la otra encima, con mucho cuidado.",
	["leans back and looks toward the water."] = "se echa hacia atrás y mira hacia el agua.",
	["leans back and stretches both hands toward the warmth."] = "se echa hacia atrás y estira las dos manos hacia el calor.",
	["leans back with both hands behind their head."] = "se reclina con las dos manos detrás de la cabeza.",
	["leans back, still studying {target}, one eye narrowed."] = "se echa hacia atrás, sin dejar de estudiar a {target}, con un ojo entrecerrado.",
	["leans down and lays two fingers on the ground, then goes very still."] = "se agacha y apoya dos dedos en el suelo, y luego se queda inmóvil.",
	["leans down and presses one palm flat against the ground."] = "se agacha y apoya la palma de la mano en el suelo.",
	["leans down and studies the ground, then glances up, smirking."] = "se agacha a estudiar el suelo, luego levanta la vista con una sonrisa burlona.",
	["leans forward and lowers their voice, one eye on the dark beyond the fire."] = "se inclina hacia adelante y baja la voz, con un ojo en la oscuridad más allá del fuego.",
	["leans forward and pats their hands quickly against their knees, like feet on hard ground."] = "se inclina hacia adelante y se da palmaditas rápidas en las rodillas, como pasos sobre tierra dura.",
	["leans forward and works at an imaginary keyhole, tongue between their teeth."] = "se inclina y trabaja en una cerradura imaginaria, con la lengua entre los dientes.",
	["leans forward slightly, then back, then forward again, listening each time."] = "se inclina un poco hacia adelante, luego hacia atrás, luego adelante otra vez, escuchando cada vez.",
	["leans forward, pokes at something invisible with a stick, and sniffs thoughtfully."] = "se inclina, pica algo invisible con una vara y lo olfatea con aire pensativo.",
	["leans forward, raises one hand, and waits, watching the ground."] = "se inclina hacia adelante, levanta una mano y espera, mirando el suelo.",
	["leans hard to one side, arms braced, squinting into driving rain."] = "se inclina con fuerza hacia un lado, con los brazos firmes, entornando los ojos contra la lluvia.",
	["leans in and drops their voice, as if the captain might still overhear."] = "se inclina hacia adelante y baja la voz, como si la capitana todavía pudiera oírlo.",
	["leans in close to the fire and lowers their voice."] = "se acerca al fuego y baja la voz.",
	["leans in over the fire, so the light climbs their face, and lowers their voice."] = "se inclina sobre el fuego, de modo que la luz le sube por la cara, y baja la voz.",
	["leans lightly on an invisible pole, barely pressing."] = "se apoya levemente en una pértiga invisible, casi sin hacer fuerza.",
	["leans out with arms spread for balance, and glances down at a long drop."] = "se asoma con los brazos abiertos para mantener el equilibrio, y mira el vacío allá abajo.",
	["leans over and brushes something away with one hand, then looks closer."] = "se inclina y aparta algo con una mano, luego se acerca más a mirar.",
	["leans over and lifts a stone with great care."] = "se inclina y levanta una piedra con muchísimo cuidado.",
	["leans over and runs a hand across the grass, then wipes it on their coat."] = "se inclina y pasa una mano por el pasto, y luego se la limpia en el abrigo.",
	["leans over to peer in the direction of {target}'s boots, then winces."] = "se inclina para mirar hacia las botas de {target} y hace una mueca.",
	["leans sideways with arms outspread, one hand clutching an imaginary wrench."] = "se inclina hacia un lado con los brazos extendidos, aferrando una llave inglesa imaginaria con una mano.",
	["leans to one side and peers around something tall, then winces."] = "se inclina hacia un lado para asomarse detrás de algo alto, y luego hace una mueca.",
	["leans toward the fire, raises one finger, and tilts their head as though listening."] = "se inclina hacia el fuego, levanta un dedo y ladea la cabeza como si escuchara.",
	["leans toward the fire."] = "se inclina hacia el fuego.",
	["leans toward the firelight, as if about to share a secret."] = "se inclina hacia la luz del fuego, como quien va a contar un secreto.",
	["leans toward {target} with great seriousness, hands folded."] = "se inclina hacia {target} con gran seriedad, con las manos entrelazadas.",
	["lets a long silence go by, watching the smoke above the flames."] = "deja pasar un largo silencio, mirando el humo sobre las llamas.",
	["lets go of the levers and raises both hands, grinning."] = "suelta las palancas y levanta las dos manos con una gran sonrisa.",
	["lets go of their own sleeves and settles both hands in their lap."] = "suelta sus propias mangas y apoya ambas manos en el regazo.",
	["lets one hand hang low at their side, fingers moving as if scratching an ear."] = "deja caer una mano junto al costado, moviendo los dedos como si rascara una oreja.",
	["lets one hand hang low, palm open, and leaves it there."] = "deja colgar una mano, con la palma abierta, y la deja ahí.",
	["lets the fire tick and settle for a while before going on."] = "deja que el fuego chisporrotee y se asiente un rato antes de seguir.",
	["lets the silence sit a moment before saying anything else."] = "deja que el silencio dure un momento antes de decir nada más.",
	["lets the silence sit so long that a log settling in the fire sounds loud."] = "deja que el silencio dure tanto que un leño al acomodarse en el fuego suena fuerte.",
	["lets their eyes drift past the firelight into the dark, and keeps them there a little too long."] = "deja que la mirada se le pierda más allá de la luz del fuego, en la oscuridad, y la deja ahí un poquito demasiado.",
	["licks a fingertip, holds it up gravely, and nods as if it has told them something important."] = "se chupa la punta de un dedo, lo levanta con gravedad y asiente, como si le hubiera dicho algo importante.",
	["lifts a cup carefully in both hands, then sniffs it."] = "levanta con cuidado una copa con las dos manos, y luego la huele.",
	["lifts a hand in a small wave."] = "levanta una mano en un pequeño saludo.",
	["lifts a wet finger into the air, holds it there, and slowly lowers it."] = "levanta un dedo mojado al aire, lo sostiene ahí y lo baja despacio.",
	["lifts an invisible cup, blows across it, and sips with great care."] = "levanta una taza invisible, sopla encima y da un sorbo con mucho cuidado.",
	["lifts an invisible heavy sack to shoulder height and holds it there, waiting."] = "levanta un pesado costal invisible a la altura del hombro y lo sostiene ahí, esperando.",
	["lifts an unseen plate and wipes it, very gently, with their sleeve."] = "levanta un plato invisible y lo limpia, con mucha delicadeza, con la manga.",
	["lifts one finger and gives a tiny invisible bell a single tap."] = "levanta un dedo y le da un solo toquecito a una campanilla invisible diminuta.",
	["lifts one fist and brings it down sharply, as if striking with a hammer of light."] = "alza un puño y lo baja de golpe, como si golpeara con un martillo de luz.",
	["lifts one hand and studies the shadow it casts, turning it slowly."] = "alza una mano y estudia la sombra que proyecta, girándola despacio.",
	["lifts one hand slowly, as if stepping over something, then lets it settle."] = "levanta una mano despacio, como si pasara por encima de algo, y luego la deja posarse.",
	["lifts the lid of an invisible box, very slowly."] = "levanta la tapa de una caja invisible, muy despacio.",
	["lifts the stone to their ear and goes quiet."] = "se acerca la piedra al oído y se queda en silencio.",
	["lifts their chin and answers softly to no one, \"Here.\""] = "levanta la barbilla y responde en voz baja a nadie: «Presente».",
	["lifts their chin and looks down their nose, cold as a winter morning."] = "alza la barbilla y mira a todos desde arriba, con la frialdad de una mañana de invierno.",
	["lifts their chin and sniffs at the air, then wishes they hadn't."] = "alza la barbilla y olfatea el aire, y luego se arrepiente.",
	["lifts their hand off the ground beside the fire, slowly, and listens."] = "levanta despacio la mano del suelo junto al fuego, y escucha.",
	["linen cloth"] = "el paño de lino",
	["links their fingers together, then pulls hard with both arms."] = "entrelaza los dedos y luego jala con fuerza con ambos brazos.",
	["listens to the fire tick and pop, counting under their breath, then stops."] = "escucha el fuego chasquear y crepitar, contando entre dientes, y luego se detiene.",
	["looks above the firelight for a long, quiet moment."] = "mira en silencio, durante un largo rato, por encima de la luz del fuego.",
	["looks around at an unseen slope and gives a small, tired shrug."] = "mira a su alrededor una ladera que nadie más ve y se encoge de hombros con cansancio.",
	["looks around the circle and lets the question hang, one eyebrow up."] = "recorre el círculo con la mirada y deja la pregunta en el aire, con una ceja levantada.",
	["looks around the circle and nods once at each listener, as if daring one of them to ask."] = "recorre el círculo con la mirada y asiente una vez ante cada oyente, como desafiando a alguno a preguntar.",
	["looks around the circle with raised eyebrows, waiting for someone to ask."] = "recorre el círculo con la mirada y las cejas levantadas, esperando a que alguien pregunte.",
	["looks around the circle, daring someone to ask the obvious question."] = "recorre el círculo con la mirada, retando a alguien a hacer la pregunta obvia.",
	["looks at the ground near {target} and goes quiet."] = "mira el suelo cerca de {target} y guarda silencio.",
	["looks at the log in their hand, and sets it down beside the fire instead of on it."] = "mira el leño que tiene en la mano, y lo deja junto al fuego en vez de echarlo.",
	["looks at their empty hands, then follows something slow along the ground with their eyes."] = "se mira las manos vacías y luego sigue con la vista algo que avanza lento por el suelo.",
	["looks at their hands, then slowly folds them out of sight."] = "se mira las manos y luego las esconde despacio.",
	["looks at their open hand for a moment, then closes it gently."] = "se mira la mano abierta un momento y luego la cierra con suavidad.",
	["looks at {target} across the flames for a little too long, then looks away."] = "mira a {target} por encima de las llamas un poco más de la cuenta, y luego aparta la vista.",
	["looks at {target}, then back into the fire."] = "mira a {target} y luego vuelve a mirar el fuego.",
	["looks away and runs a thumb slowly along the edge of their sleeve."] = "desvía la mirada y pasa el pulgar despacio por el borde de la manga.",
	["looks down at the coals."] = "baja la mirada a las brasas.",
	["looks down at the fire, then at the ground beneath it, and nudges a stray coal back into the ring."] = "mira el fuego, luego el suelo debajo, y empuja una brasa perdida de vuelta al círculo.",
	["looks down at their boots, not sure how to go on."] = "se mira las botas, sin saber cómo seguir.",
	["looks down at their hands and slowly opens them."] = "baja la vista a sus manos y las abre despacio.",
	["looks down at their hands, working at an invisible length of rope."] = "se mira las manos, que trabajan en un trozo de cuerda invisible.",
	["looks down at their own boot, and holds very still."] = "mira su propia bota y no mueve ni un músculo.",
	["looks down at their own hands and turns them over slowly."] = "se mira las manos y las voltea despacio.",
	["looks down at their wrist and gives it a small, testing shake."] = "se mira la muñeca y le da una pequeña sacudida de prueba.",
	["looks down fondly at a spot near their feet."] = "mira con cariño un punto cerca de sus pies.",
	["looks down into their cup for a moment, smiling a little."] = "mira el fondo de su taza un momento, con una pequeña sonrisa.",
	["looks down, startled, and slowly lowers one raised arm."] = "mira hacia abajo con un sobresalto y, despacio, baja un brazo que tenía en alto.",
	["looks from one side to the other, slowly, and then back again."] = "mira de un lado al otro, despacio, y luego vuelve a mirar.",
	["looks into the fire for a long moment, then nods once."] = "se queda mirando el fuego un largo rato y luego asiente una vez.",
	["looks into the fire."] = "mira el fuego.",
	["looks off into the dark beyond the circle, jaw tight."] = "mira hacia la oscuridad más allá del círculo, con la mandíbula apretada.",
	["looks off into the dark, as if counting distant campfires."] = "mira hacia la oscuridad, como si contara fogatas lejanas.",
	["looks off into the distance, as if over still water, and goes quiet for a moment."] = "mira a lo lejos, como sobre agua quieta, y se queda en silencio un momento.",
	["looks out at some high, distant point and takes a slow breath."] = "mira hacia algún punto alto y lejano, y respira despacio.",
	["looks out over the heads of the circle, as if at a far-off valley."] = "mira por encima de las cabezas del círculo, como hacia un valle lejano.",
	["looks past the firelight at the black trees, and very carefully does not answer them."] = "mira más allá de la luz del fuego hacia los árboles negros, y con mucho cuidado no les contesta.",
	["looks skyward and slowly hunches their shoulders, as if something were circling."] = "mira al cielo y encoge despacio los hombros, como si algo diera vueltas allá arriba.",
	["looks slowly around the circle, at each face the firelight reaches, and then away."] = "recorre despacio el círculo con la mirada, cada rostro que alcanza la luz del fuego, y luego aparta los ojos.",
	["looks slowly around the circle, lips moving as if counting."] = "recorre despacio el círculo con la mirada, moviendo los labios como si contara.",
	["looks slowly down at their own hands, and draws them in close to the fire."] = "baja la vista despacio hacia sus manos, y las acerca al fuego.",
	["looks slowly to either side, searching, then lowers their gaze."] = "mira despacio a un lado y al otro, buscando, y luego baja la mirada.",
	["looks slowly upward, then back down at the ground by their feet."] = "mira despacio hacia arriba y luego vuelve a mirar el suelo junto a sus pies.",
	["looks up at the moon."] = "alza la vista hacia la luna.",
	["looks up at the sky."] = "mira al cielo.",
	["looks up slowly, then down at their own feet, frowning."] = "alza la vista despacio, luego mira sus propios pies y frunce el ceño.",
	["looks up toward the mountains."] = "alza la vista hacia las montañas.",
	["looks {target} up and down, counting something on their fingers."] = "mira a {target} de arriba abajo, contando algo con los dedos.",
	["lowers a bow and breathes out slowly."] = "baja un arco y suelta el aire despacio.",
	["lowers an invisible lantern slowly, then stops short and pulls it back."] = "baja despacio un farol invisible, se detiene en seco y lo retira.",
	["lowers the invisible spoon and shakes their head slowly."] = "baja el cucharón invisible y niega despacio con la cabeza.",
	["lowers their gaze and walks two fingers slowly along one knee, as if following something along the ground."] = "baja la mirada y hace caminar despacio dos dedos sobre una rodilla, como siguiendo algo por el suelo.",
	["lowers their head and rests both hands on their weapon."] = "baja la cabeza y apoya ambas manos en su arma.",
	["lowers their head and sinks their shoulders slowly, like something going under."] = "baja la cabeza y hunde los hombros despacio, como algo que se va al fondo.",
	["lowers their voice and glances over one shoulder at nobody."] = "baja la voz y mira por encima del hombro, aunque no hay nadie.",
	["lowers their voice."] = "baja la voz.",
	["lunges forward and snaps one hand shut, then hauls it back."] = "se lanza hacia adelante y cierra una mano de golpe, y luego la jala hacia atrás.",
	["makes a small gurgling noise, then looks embarrassed."] = "hace un gorgoteo y luego pone cara de vergüenza.",
	["makes a small, courteous bow, then another, then catches themselves halfway through a third."] = "hace una reverencia pequeña y cortés, luego otra, y se detiene a mitad de una tercera.",
	["mimes a short, patient tap against the ground, over and over."] = "imita un golpecito corto y paciente contra el suelo, una y otra vez.",
	["mimes lifting the lid of a heavy chest, then lets their shoulders drop."] = "hace como que levanta la tapa de un cofre pesado, y luego deja caer los hombros.",
	["mimes peeling something wet from their sleeve, with growing disgust."] = "hace como que se despega algo mojado de la manga, cada vez con más asco.",
	["mimes reaching down, lifting, and setting something gently on the ground."] = "hace como que se agacha, levanta algo y lo deja con cuidado en el suelo.",
	["mimes shaping a snowball between their palms and gives one short, hopeless throw."] = "hace como que moldea una bola de nieve entre las palmas y la lanza, cortito y sin ninguna esperanza.",
	["mouths a word carefully and silently, as if practicing it."] = "articula una palabra con cuidado y en silencio, como si la practicara.",
	["moves one hand as if brushing through hanging leaves."] = "mueve una mano como si apartara hojas que cuelgan.",
	["moves one hand forward, stops it suddenly, and waits with their head on one side."] = "mueve una mano hacia adelante, la detiene de golpe y espera con la cabeza ladeada.",
	["moves their lips silently for a moment, eyes closed."] = "mueve los labios en silencio un momento, con los ojos cerrados.",
	["narrows their eyes and leans closer to something invisible, then draws back sharply."] = "entrecierra los ojos y se acerca a algo invisible, y luego se echa atrás de golpe.",
	["narrows their eyes and shifts their weight, as if sizing someone up."] = "entrecierra los ojos y pasa el peso de un pie al otro, como si midiera a alguien.",
	["narrows their eyes at {target}, then slowly grins."] = "entrecierra los ojos mirando a {target} y luego sonríe despacio.",
	["narrows their eyes, as though at some small and hated foe."] = "entrecierra los ojos, como ante algún enemigo pequeño y odiado.",
	["nods at the fire and shows their tusks in a wide, lazy grin."] = "señala el fuego con la cabeza y muestra los colmillos en una sonrisa amplia y perezosa.",
	["nods once, as if that's the end of the matter."] = "asiente una vez, como dando el asunto por terminado.",
	["nods slowly and approvingly, as if at a fine piece of work."] = "asiente despacio con aprobación, como ante un trabajo bien hecho.",
	["nods solemnly at {target}."] = "asiente con solemnidad mirando a {target}.",
	["nods to {target} and settles back."] = "le hace un gesto con la cabeza a {target} y se acomoda hacia atrás.",
	["nudges a log deeper into the coals."] = "empuja un leño más adentro de las brasas.",
	["opens a pack, reaches in, and pulls their hand back quickly."] = "abre una mochila, mete la mano y la saca rápido.",
	["opens one hand and studies the middle of the palm in the firelight."] = "abre una mano y se estudia el centro de la palma a la luz del fuego.",
	["opens one hand slowly and looks at what would be lying in it."] = "abre despacio una mano y mira lo que habría en ella.",
	["opens one hand to reveal a small, dark seed, worn smooth with handling."] = "abre una mano y muestra una semilla pequeña y oscura, pulida de tanto tocarla.",
	["opens their mouth to answer, then thoughtfully closes it."] = "abre la boca para responder, y luego la cierra, con aire pensativo.",
	["opens their mouth to speak, then closes it and looks down at their hands."] = "abre la boca para hablar, la cierra y se mira las manos.",
	["passes something heavy from one hand to the other, again and again, quickly."] = "pasa algo pesado de una mano a la otra, una y otra vez, rápido.",
	["pats a small pouch at their belt, and lets their hand stay there."] = "le da unas palmaditas a una bolsita que lleva al cinto, y deja la mano ahí.",
	["pats an invisible pack at their side."] = "palmea una mochila invisible que lleva al costado.",
	["pats the air at shoulder height, as if feeling for something worn."] = "palpa el aire a la altura del hombro, como buscando algo gastado.",
	["pats the empty ground beside them."] = "da unas palmaditas en el suelo vacío a su lado.",
	["pats the ground beside them as if greeting an old friend, nodding slowly."] = "le da unas palmaditas al suelo a su lado, como quien saluda a un viejo amigo, asintiendo despacio.",
	["pats their own face and arms, as if checking they're all still there."] = "se palpa la cara y los brazos, como para comprobar que todo sigue en su lugar.",
	["pats their pack gently."] = "le da unas palmaditas suaves a su mochila.",
	["pats their pockets, then turns one inside out."] = "se palpa los bolsillos y luego voltea uno al revés.",
	["pats their stomach slowly with one hand, looking wounded."] = "se da palmaditas en la panza con una mano, despacio, con cara de ofensa.",
	["pats their stomach, then holds up one finger as though something has just occurred to them."] = "se da palmaditas en la panza y luego alza un dedo, como si se le acabara de ocurrir algo.",
	["pats their thigh twice, softly, and looks down."] = "se da dos palmaditas suaves en el muslo y baja la mirada.",
	["pauses with an imaginary spoon halfway to their mouth."] = "se detiene con una cuchara imaginaria a medio camino de la boca.",
	["pauses with an invisible spoon halfway to their mouth, then slowly lowers it."] = "se detiene con una cuchara invisible a medio camino de la boca, y luego la baja despacio.",
	["pauses, and raises a hand as if holding up a lantern."] = "hace una pausa y levanta una mano como si sostuviera un farol.",
	["peacebloom"] = "la flor de paz",
	["peels back a blanket and peers in, without any sudden movements."] = "levanta una manta y se asoma, sin hacer movimientos bruscos.",
	["peels something sticky off their sleeve, and then has trouble getting it off their fingers."] = "se despega algo pegajoso de la manga, y luego no logra quitárselo de los dedos.",
	["peers at the ground near {target}, watching how the firelight falls."] = "mira el suelo cerca de {target}, observando cómo cae la luz del fuego.",
	["peers between their fingers, as if through leaves, at something far off."] = "se asoma entre sus dedos, como entre hojas, hacia algo lejano.",
	["peers down into cupped hands, searching for something small."] = "se asoma a sus manos ahuecadas, buscando algo pequeño.",
	["peers into a bowl, then gives it a polite nod."] = "se asoma a un tazón y luego le dedica un gesto cortés con la cabeza.",
	["peers off toward the hills, chewing slowly."] = "mira hacia las colinas a lo lejos, masticando despacio.",
	["peers over an imaginary edge and slowly draws back, swallowing."] = "se asoma por un borde imaginario y retrocede despacio, tragando saliva.",
	["peers suspiciously into an imaginary bowl and stirs it with one finger."] = "mira con desconfianza un plato imaginario y lo revuelve con un dedo.",
	["picks a twig from the kindling, considers how long it took to grow, and feeds it to the fire anyway."] = "toma una ramita de la leña, considera cuánto tardó en crecer y la echa al fuego de todos modos.",
	["picks an invisible crumb from their own chin, and studies it."] = "se quita una migaja invisible de la barbilla y se pone a estudiarla.",
	["picks an invisible lock with two fingers, then freezes with their head cocked."] = "abre una cerradura invisible con dos dedos y luego se queda inmóvil, con la cabeza ladeada.",
	["picks at an invisible knot with blunt, patient fingers."] = "trata de aflojar un nudo invisible con dedos toscos y pacientes.",
	["picks at an invisible knot with their fingertips, frowning."] = "pellizca un nudo invisible con las yemas de los dedos, con el ceño fruncido.",
	["pinches an invisible line between two fingers and lets it droop slowly."] = "pellizca un hilo invisible entre dos dedos y lo deja caer despacio.",
	["pinches an invisible needle and draws a slow thread through the air."] = "toma una aguja invisible entre los dedos y tira despacio de un hilo por el aire.",
	["pinches an invisible thread and lifts it carefully clear of something below."] = "pellizca un hilo invisible y lo levanta con cuidado por encima de algo.",
	["pitches forward with arms spread wide, then jerks upward as if yanked by the collar."] = "se va de bruces con los brazos abiertos y luego sube de golpe, como si le dieran un tirón del cuello.",
	["plants both hands flat on their knees and sets their shoulders, immovable."] = "apoya ambas manos sobre las rodillas y cuadra los hombros, inamovible.",
	["plants their fists on their hips and glares at the ground, jaw thrust forward."] = "se planta con los puños en la cintura y fulmina el suelo con la mirada, sacando la quijada.",
	["plants their hands on their hips and looks up, like someone addressing a stubborn child."] = "se pone las manos en la cintura y mira hacia arriba, como quien regaña a un niño terco.",
	["plants their hands on their hips and surveys a vast and empty view."] = "pone las manos en la cintura y contempla un paisaje enorme y vacío.",
	["points around in a slow circle, lips moving silently."] = "señala alrededor en un círculo lento, moviendo los labios sin voz.",
	["points at two spots on their open palm, one and then the other."] = "señala dos puntos en la palma abierta, primero uno y luego el otro.",
	["points left with one hand, right with the other, and then tries to point up with an elbow."] = "señala a la izquierda con una mano, a la derecha con la otra, y luego intenta señalar hacia arriba con el codo.",
	["points left, then right, then gives their own hand a puzzled look."] = "señala a la izquierda, luego a la derecha, y luego se mira la mano con cara de no entender.",
	["points north with a stick from the fire."] = "señala hacia el norte con una rama de la fogata.",
	["points once toward the fire ring, pauses, and lowers their hand without finishing the count."] = "señala una vez hacia el círculo de la fogata, se detiene, y baja la mano sin terminar de contar.",
	["points slowly around the circle where they sit, at nothing in particular."] = "señala despacio todo el círculo alrededor del fuego, sin apuntar a nada en particular.",
	["pokes a stick into the coals and considers it gravely."] = "remueve las brasas con un palo y las contempla con seriedad.",
	["pokes at the fire and watches the sparks climb."] = "atiza el fuego y mira cómo suben las chispas.",
	["pokes the fire and watches the sparks climb."] = "atiza el fuego y mira cómo suben las chispas.",
	["pokes the fire twice and clears their throat, a little too loudly."] = "atiza el fuego dos veces y carraspea, un poco demasiado fuerte.",
	["pokes the fire until it crackles, then looks around the circle."] = "atiza el fuego hasta que chisporrotea y luego mira a todos en el círculo.",
	["pokes their tongue into their cheek and winces."] = "se empuja el cachete con la lengua y hace una mueca de dolor.",
	["pops something imaginary into their mouth and chews happily."] = "se echa algo imaginario a la boca y mastica con gusto.",
	["pounds out a rhythm on their thigh that falls apart almost at once."] = "marca un ritmo en su muslo que se desbarata casi de inmediato.",
	["presses a hand flat over their heart and lets out a long breath."] = "se pone una mano sobre el corazón y suelta un largo suspiro.",
	["presses a palm flat against their chest, then lets it fall."] = "se pone la palma de la mano en el pecho y luego la deja caer.",
	["presses an ear to an unseen pipe and holds their breath."] = "pega la oreja a un tubo que nadie ve y contiene la respiración.",
	["presses one finger to their lips and looks up, not moving at all."] = "se lleva un dedo a los labios y mira hacia arriba, sin moverse en absoluto.",
	["presses one palm against the empty air and slowly draws it back."] = "apoya una palma contra el aire vacío y la retira despacio.",
	["presses one thumb gently into the center of their other palm."] = "presiona suavemente un pulgar en el centro de la otra palma.",
	["presses their lips together and gives a small, stiff nod."] = "aprieta los labios y asiente apenas, con rigidez.",
	["presses their thumb into the palm of their other hand and holds it there."] = "presiona el pulgar contra la palma de la otra mano y lo deja ahí un momento.",
	["pretends to gallop with both hands."] = "finge galopar con las dos manos.",
	["pretends to pour something from nothing."] = "finge servir algo de la nada.",
	["prods a charred log with a stick, twice, just to be sure."] = "pica un leño chamuscado con una vara, dos veces, nada más para asegurarse.",
	["puckers their mouth and swallows hard at the memory."] = "frunce la boca y traga saliva con fuerza al recordarlo.",
	["puffs out their cheeks and frowns up at the sky."] = "infla los cachetes y frunce el ceño mirando al cielo.",
	["puffs out their chest proudly, then lets it sag."] = "saca el pecho con orgullo y luego lo deja desinflarse.",
	["puffs up their chest."] = "infla el pecho.",
	["pulls a knot tight in an invisible rope, and keeps both hands on it."] = "aprieta un nudo en una cuerda invisible y la sigue sujetando con ambas manos.",
	["pulls a loose thread from their sleeve and drops it in the flames without a word."] = "jala un hilo suelto de su manga y lo deja caer a las llamas sin decir nada.",
	["pulls a loose thread from their sleeve and lets the updraft off the fire carry it away."] = "se saca un hilo suelto de la manga y deja que el aire caliente del fuego se lo lleve.",
	["pulls a small feather from nowhere and smooths it between their fingers."] = "saca una plumita de la nada y la alisa entre los dedos.",
	["pulls a worn spoon from their belt and gives it a little flourish."] = "saca del cinturón una cuchara gastada y la blande con un floreo.",
	["pulls an invisible folded letter from a pocket and frowns at it, then at {target}."] = "saca de un bolsillo una carta doblada invisible y la mira con el ceño fruncido, y luego a {target}.",
	["pulls at something around their neck, and holds the end up to look at it."] = "tira de algo que lleva al cuello y levanta la punta para mirarla.",
	["pulls off an invisible coat, throws it over something, then tugs gently on a lead."] = "se quita un abrigo invisible, lo echa sobre algo, y luego jala suavemente de una rienda.",
	["pulls on one invisible glove, then another over it, flexing their fingers."] = "se pone un guante invisible, luego otro encima, y flexiona los dedos.",
	["pulls slowly on an invisible rope, then again, keeping time."] = "jala despacio una cuerda invisible, y luego otra vez, llevando el ritmo.",
	["pulls their coat closed and turns their face out of the firelight."] = "se cierra el abrigo y aparta la cara de la luz del fuego.",
	["pulls their hand back from the fire quickly."] = "aparta rápido la mano del fuego.",
	["pumps their arms, breathing hard, and glances back over one shoulder."] = "mueve los brazos como si corriera, jadeando, y echa un vistazo por encima del hombro.",
	["pumps their elbows where they sit, breathing hard."] = "mueve los codos sin levantarse, jadeando.",
	["purses their lips and whistles two soft notes, up and down."] = "frunce los labios y silba dos notas suaves, una arriba y otra abajo.",
	["pushes their pack an arm's length away, hesitates, and draws it close again."] = "aparta la mochila a un brazo de distancia, duda, y la vuelve a acercar.",
	["raises a cup to no one in particular."] = "alza la taza a la salud de nadie en particular.",
	["raises a finger toward the dark overhead, then lets it sink."] = "alza un dedo hacia la oscuridad de arriba y luego lo deja caer.",
	["raises a fist and brings it down slowly, as if on an unseen anvil."] = "alza un puño y lo baja despacio, como sobre un yunque invisible.",
	["raises a hand flat above their own head, as if measuring."] = "levanta una mano plana por encima de su propia cabeza, como si se midiera.",
	["raises an eyebrow and gives the fire a slow, knowing look."] = "levanta una ceja y le echa al fuego una mirada lenta y cómplice.",
	["raises an imaginary mug toward the fire."] = "alza un tarro imaginario hacia el fuego.",
	["raises an imaginary spear, sights down it, then shifts their aim a little low."] = "alza una lanza imaginaria, apunta a lo largo de ella y luego baja un poco la puntería.",
	["raises an invisible bucket a little way, holds it there, and then sets it down again."] = "levanta un poquito una cubeta invisible, la sostiene ahí, y luego la vuelve a bajar.",
	["raises an invisible vial to the firelight."] = "alza un frasquito invisible hacia la luz del fuego.",
	["raises an unsteady hand and sways where they sit, squinting along an invisible blade."] = "alza una mano temblorosa y se tambalea en su sitio, mirando el filo de una hoja invisible con los ojos entrecerrados.",
	["raises both arms and sways solemnly from side to side."] = "alza ambos brazos y se balancea solemnemente de lado a lado.",
	["raises both fists and brings them down hard on an invisible drum, once, twice."] = "levanta ambos puños y los descarga con fuerza sobre un tambor invisible, una vez, dos veces.",
	["raises both fists as if gripping a hilt and braces against the air."] = "alza los dos puños como si empuñara una espada y se planta firme contra el aire.",
	["raises both hands as if gripping an axe, then brings them down hard."] = "levanta las dos manos como si empuñara un hacha y las baja con fuerza.",
	["raises both hands solemnly, then winces at the memory."] = "alza ambas manos con solemnidad, y luego hace una mueca al recordarlo.",
	["raises both palms, as if calming two arguing friends."] = "levanta ambas palmas, como quien calma a dos amigos que se pelean.",
	["raises one arm overhead at an angle, bracing it with the other hand, and winces at each blow."] = "levanta un brazo en ángulo sobre la cabeza, lo apuntala con la otra mano y hace una mueca con cada golpe.",
	["raises one finger to explain, thinks better of it, and lowers it slowly."] = "alza un dedo para explicar, lo piensa mejor y lo baja despacio.",
	["raises one hand near the fire and studies the shadow between their fingers."] = "alza una mano junto al fuego y estudia la sombra entre sus dedos.",
	["raises one hand solemnly, as if casting a vote."] = "levanta una mano con solemnidad, como si emitiera su voto.",
	["raises one open hand quickly, fingers spread, and holds it there."] = "levanta rápido una mano abierta, con los dedos extendidos, y la sostiene ahí.",
	["raises their cup, solemnly, as if to a worthy opponent."] = "alza su taza con solemnidad, como ante un rival digno.",
	["rakes the coals together with a stick, saving the heat."] = "junta las brasas con un palo, para guardar el calor.",
	["raps their knuckles three times on the ground, then waits."] = "golpea tres veces el suelo con los nudillos, y espera.",
	["raps three times on the ground beside them, then waits, head tilted."] = "golpea tres veces el suelo a su lado y espera, con la cabeza ladeada.",
	["reaches out and gently smooths a strand of invisible hair."] = "extiende la mano y alisa con ternura un mechón de cabello invisible.",
	["reaches up and carefully snips at something overhead with two fingers."] = "estira el brazo hacia arriba y con cuidado corta algo con dos dedos.",
	["reaches up, hand over hand, breathing harder with every reach."] = "estira los brazos hacia arriba, mano tras mano, jadeando más con cada tirón.",
	["rests a hand flat on their knee and looks into the coals for a while."] = "apoya una mano sobre la rodilla y se queda un rato mirando las brasas.",
	["rests a hand on an invisible neck and pats it twice."] = "apoya la mano en un cuello invisible y le da dos palmaditas.",
	["rests one hand on the air, as if on the top of a low gate, then lets it fall."] = "apoya una mano en el aire, como sobre una reja baja, y luego la deja caer.",
	["rests their fingertips lightly over one pocket."] = "apoya suavemente las yemas de los dedos sobre un bolsillo.",
	["rolls one shoulder, as if the bruise still aches."] = "mueve un hombro en círculo, como si el moretón todavía le doliera.",
	["rolls something small between finger and thumb, then flicks it away."] = "hace rodar algo pequeño entre el índice y el pulgar, y luego lo lanza lejos de un capirotazo.",
	["rolls their neck and stretches, in a distinctly animal way."] = "estira el cuello en círculos y se despereza, de una manera claramente animal.",
	["rolls their shoulders, then tilts slowly into some unfelt gust."] = "mueve los hombros en círculo y luego se inclina despacio hacia una ráfaga que nadie más siente.",
	["rolls up one sleeve to show an old, crescent-shaped scar."] = "se sube una manga y enseña una vieja cicatriz en forma de media luna.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, and smiles."] = "frota entre los dedos una pizca de ceniza fría del borde de la fogata, y sonríe.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, with some satisfaction."] = "frota entre los dedos una pizca de ceniza fría del borde del fuego, con cierta satisfacción.",
	["rubs a thumb across their own palm, as if the handshake were still there."] = "se pasa un pulgar por la palma, como si el apretón de manos siguiera ahí.",
	["rubs a thumb across their palm, as if wiping dirt off something small."] = "se frota la palma con el pulgar, como si le limpiara la tierra a algo pequeño.",
	["rubs a thumb and two fingers together."] = "frota el pulgar contra dos dedos.",
	["rubs a thumb in small, firm circles over one palm."] = "frota un pulgar en círculos pequeños y firmes sobre una palma.",
	["rubs an invisible coin between finger and thumb."] = "frota una moneda invisible entre el índice y el pulgar.",
	["rubs both wrists slowly, as if feeling old chains."] = "se frota las muñecas despacio, como si sintiera viejas cadenas.",
	["rubs finger and thumb together as though testing a pinch of grit."] = "frota el índice y el pulgar como si probara una pizca de arenilla.",
	["rubs finger and thumb together, as though testing a pinch of soil."] = "frota el índice y el pulgar, como si probara una pizca de tierra.",
	["rubs the back of their neck, and looks down at the fire."] = "se frota la nuca y baja la mirada al fuego.",
	["rubs the back of their neck, sheepish."] = "se rasca la nuca con cara de vergüenza.",
	["rubs the side of one thumb slowly across their palm."] = "frota despacio el costado de un pulgar contra la palma.",
	["rubs their fingers together, as if brushing away soot."] = "se frota los dedos, como si se sacudiera hollín.",
	["rubs their hands together by the fire."] = "se frota las manos junto al fuego.",
	["rubs their thumb and fingers together as though testing for dust, then stops themselves."] = "se frota el pulgar contra los dedos como buscando polvo, y luego se detiene.",
	["runs a finger slowly down an invisible page, then stops."] = "recorre despacio con un dedo una página invisible y luego se detiene.",
	["runs a fingertip along an imaginary seam on their sleeve."] = "pasa la yema de un dedo por una costura imaginaria de la manga.",
	["runs a hand low through the air, near the knee, as if along an old wall."] = "pasa una mano por el aire a la altura de la rodilla, como si recorriera un muro viejo.",
	["runs a length of old cord through their fingers, stopping at each knot."] = "pasa un trozo de cordel viejo entre los dedos, deteniéndose en cada nudo.",
	["runs a slow hand along an invisible length of wood, feeling for the grain."] = "pasa despacio una mano por un trozo de madera invisible, buscando la veta.",
	["runs a thumb along an invisible edge."] = "pasa el pulgar por un filo invisible.",
	["runs a thumb along an old notch in their weapon."] = "pasa el pulgar por una vieja muesca de su arma.",
	["runs a thumb along the nicks in their blade."] = "pasa el pulgar por las mellas de su hoja.",
	["runs a thumb over a board, then stops at something and looks closer."] = "pasa un pulgar por un tablón, se detiene en algo y lo mira más de cerca.",
	["runs one finger down an invisible page, then stops."] = "recorre con un dedo una página invisible, y se detiene.",
	["says nothing more, and watches the black branches lean a little closer over the firelight."] = "no dice nada más, y observa cómo las ramas negras se inclinan un poco más sobre la luz del fuego.",
	["scoops up a handful of dirt and lets it sift through their fingers."] = "recoge un puñado de tierra y deja que se le escurra entre los dedos.",
	["scoops up a handful of imaginary dirt, frowns at it, and lets it run through their fingers."] = "recoge un puñado de tierra imaginaria, la mira con el ceño fruncido y la deja escurrir entre los dedos.",
	["scratches a slow line in the ashes with a stick, then adds another beneath it."] = "traza despacio una raya en la ceniza con una vara, y luego agrega otra debajo.",
	["scratches an imaginary companion behind the ears."] = "rasca detrás de las orejas a un compañero imaginario.",
	["scuttles two fingers along an imaginary track, grinning wide."] = "hace correr dos dedos por una pista imaginaria, con una gran sonrisa.",
	["sets a scrap of jerky down beside them, where an old dog might find it."] = "deja un trozo de cecina a su lado, donde un perro viejo podría encontrarlo.",
	["sets a scrap of their dinner at the edge of the firelight, and does not look to see what comes."] = "deja un pedazo de su cena al borde de la luz del fuego, y no mira qué viene por él.",
	["sets a small stone on the ring around the fire, then a second beside it, and says no more."] = "pone una piedrita en el círculo alrededor del fuego, luego otra a su lado, y no dice más.",
	["sets one shoulder low and pushes slowly forward, jaw tight."] = "baja un hombro y empuja despacio hacia adelante, con la mandíbula apretada.",
	["sets one thing on top of another, with great care, and sits back."] = "pone una cosa encima de otra, con muchísimo cuidado, y se echa hacia atrás.",
	["sets something down with both hands and does not look up."] = "deja algo en el suelo con ambas manos y no levanta la vista.",
	["sets something heavy down carefully and eases themselves back with a long breath."] = "deja algo pesado en el suelo con cuidado y se recuesta con un largo suspiro.",
	["sets the stick down and nods across the flames at {target}."] = "deja el palo y le hace un gesto con la cabeza a {target} por encima de las llamas.",
	["sets the stone by the ring of the fire, carefully, as if leaving it for someone."] = "deja la piedra junto al círculo del fuego, con cuidado, como si la dejara para alguien.",
	["sets their two fists side by side, then opens a small gap between them."] = "pone los dos puños lado a lado y luego abre un pequeño hueco entre ellos.",
	["settles lower, as though easing onto the edge of a cot."] = "se acomoda más abajo, como quien se sienta despacio en el borde de un catre.",
	["settles their weight with a grunt and starts unlacing an imaginary boot with great care."] = "se acomoda con un gruñido y empieza a desatar con mucho cuidado una bota imaginaria.",
	["shades their eyes and cranes their neck, squinting past the firelight."] = "se hace sombra con la mano y estira el cuello, entrecerrando los ojos más allá de la luz del fuego.",
	["shades their eyes and peers around the circle of listeners, looking increasingly worried."] = "se hace visera con la mano y recorre con la vista el círculo de oyentes, con una preocupación cada vez mayor.",
	["shades their eyes with one hand and peers around the fire."] = "se pone una mano sobre los ojos, a modo de visera, y escudriña alrededor del fuego.",
	["shakes a fist at the sky, then stops to catch their breath."] = "agita el puño hacia el cielo y luego se detiene a recuperar el aliento.",
	["shakes a fist in the air as if ringing a bell, faster and faster."] = "agita el puño en el aire como si tocara un cencerro, cada vez más rápido.",
	["shapes a small tin in the air with both hands, then gently closes the lid."] = "da forma a una latita en el aire con las dos manos y luego cierra la tapa con suavidad.",
	["shaves a thin curl from a small piece of wood and watches it fall."] = "le saca una viruta delgada a un trocito de madera y mira cómo cae.",
	["shields a tiny flame with one hand."] = "protege una llamita con una mano.",
	["shifts an invisible weight on one shoulder and rubs the spot with a grimace."] = "se acomoda un peso invisible en el hombro y se soba con una mueca.",
	["shifts back against nothing at all and slowly, blissfully, rubs their back from side to side."] = "se recarga contra la nada y, despacio, con cara de felicidad, se rasca la espalda de un lado a otro.",
	["shifts over a little, leaving space by the fire as if for someone else."] = "se hace un poquito a un lado, dejando espacio junto al fuego, como para alguien más.",
	["shifts over to one side, leaving a space beside them."] = "se corre hacia un lado y deja un espacio libre junto a sí.",
	["shivers and pulls their cloak a little tighter."] = "se estremece y se ciñe un poco más la capa.",
	["shoves at the air with both hands, wincing with each push."] = "empuja el aire con ambas manos, haciendo una mueca con cada empujón.",
	["shoves both hands sideways through the air, hard."] = "empuja el aire hacia un lado con ambas manos, con fuerza.",
	["shoves hard at the air with both hands."] = "empuja el aire con fuerza con ambas manos.",
	["shoves something round forward with both hands, then grips the air tight."] = "empuja algo redondo hacia adelante con ambas manos y luego aprieta el aire con fuerza.",
	["sighs and shakes their head at the fire."] = "suspira y niega con la cabeza mirando el fuego.",
	["sighs."] = "suspira.",
	["sinks down slowly until their chin is tucked, eyes wide and darting."] = "se hunde despacio hasta esconder la barbilla, con los ojos muy abiertos y yendo de un lado a otro.",
	["sinks lower where they sit, with the long sigh of someone easing into a tub."] = "se hunde un poco más donde está, con el largo suspiro de quien se mete despacio en una tina.",
	["sinks slowly downward with a look of deep calm, cheeks not puffed at all."] = "se hunde despacio con una expresión de calma profunda, sin inflar los cachetes para nada.",
	["sits back from the fire and lets the story settle."] = "se echa hacia atrás y deja que la historia se asiente.",
	["sits perfectly still, one arm still raised from the throw."] = "se queda totalmente inmóvil, con un brazo todavía en alto por el tiro.",
	["sits up straight and raises one hand, palm out, like someone refusing a request."] = "se endereza y levanta una mano con la palma hacia afuera, como quien niega una petición.",
	["sits up suddenly and listens, one hand raised for silence."] = "se incorpora de golpe y escucha, con una mano en alto pidiendo silencio.",
	["sits up very slowly, arms stiff at their sides, staring ahead."] = "se endereza muy despacio, con los brazos rígidos a los costados, mirando al frente.",
	["sits up very straight, eyes fixed on something far past the firelight."] = "endereza la espalda, con los ojos fijos en algo muy lejos, más allá de la luz del fuego.",
	["sits up very straight, folds their arms, and closes their eyes."] = "endereza la espalda, se cruza de brazos y cierra los ojos.",
	["sits up with their chin level and shoulders still, as if a brimming bowl rested on their head."] = "se endereza con la barbilla derecha y los hombros quietos, como si llevara en la cabeza un cuenco a rebosar.",
	["sits very still, the firelight moving over a face that does not."] = "permanece inmóvil, y la luz del fuego se mueve sobre un rostro que no se mueve.",
	["sketches a huge curve in the air with one finger."] = "dibuja en el aire una curva enorme con un dedo.",
	["sketches a weary sign of blessing in the air, like someone swatting a fly."] = "traza en el aire una bendición cansada, como quien espanta una mosca.",
	["slaps at their neck, then their arm, then flails at the empty air."] = "se da un manotazo en el cuello, luego en el brazo, y luego manotea al aire.",
	["slashes left, slashes right, then throws an arm up against an imaginary blow."] = "lanza un tajo a la izquierda, otro a la derecha, y luego alza un brazo contra un golpe imaginario.",
	["slides half of an invisible stack of coins toward themselves, leaving the rest."] = "desliza hacia sí la mitad de una pila invisible de monedas, y deja el resto.",
	["slides three invisible cups around on the ground, fast."] = "desliza tres vasos invisibles por el suelo, a toda velocidad.",
	["slowly lowers their hands and wipes them on their knees."] = "baja las manos despacio y se las limpia en las rodillas.",
	["slowly raises their eyes upward, then lowers them again."] = "alza los ojos despacito hacia arriba y luego los vuelve a bajar.",
	["slowly tips their shoulders to the wrong side and holds there, looking uneasy."] = "inclina despacio los hombros hacia el lado equivocado y se queda así, con cara de inquietud.",
	["slumps sideways with their tongue out and eyes rolled up, perfectly still."] = "se desploma de lado con la lengua afuera y los ojos en blanco, sin moverse.",
	["smiles a little into their cup and lets the joke stand."] = "sonríe un poco hacia su taza y deja que el chiste se quede ahí.",
	["smiles and lays a hand flat over their heart."] = "sonríe y se pone una mano sobre el corazón.",
	["smiles at the fire."] = "le sonríe al fuego.",
	["smiles at {target} a little too brightly."] = "le sonríe a {target} un poquito más de la cuenta.",
	["smiles down at a folded scrap of paper they clearly cannot read."] = "sonríe mirando un papelito doblado que es obvio que no sabe leer.",
	["smiles into the fire, and doesn't say anything for a moment."] = "sonríe mirando el fuego, y por un momento no dice nada.",
	["smiles into the fire."] = "le sonríe al fuego.",
	["smiles thinly and looks away, shifting so the firelight doesn't quite reach their face."] = "sonríe apenas y aparta la vista, moviéndose para que la luz del fuego no le alcance del todo la cara.",
	["smiles to themselves."] = "sonríe para sí.",
	["smooths a fold of cloth across one knee, slowly, and leaves their hand resting on it."] = "alisa despacio un pliegue de tela sobre la rodilla y deja la mano descansando encima.",
	["smooths a patch of ground flat with the palm of one hand."] = "alisa un pedacito de suelo con la palma de la mano.",
	["smooths down the front of their shirt with a small, pleased smile."] = "se alisa el frente de la camisa con una sonrisita satisfecha.",
	["smooths down their hair, looking faintly worried."] = "se alisa el pelo, con cara de cierta preocupación.",
	["snaps a thorny branch for the fire, sucks a pricked thumb, and nods as if the point were proved."] = "parte una rama espinosa para el fuego, se chupa el pulgar pinchado y asiente como si eso lo demostrara todo.",
	["snaps their fingers, looks pleased, and then lets the smile slowly fade."] = "truena los dedos, pone cara de satisfacción, y luego deja que la sonrisa se le borre despacio.",
	["snatches at something on the ground, then hunches low with an arm over their head."] = "manotea algo en el suelo y luego se agacha con un brazo sobre la cabeza.",
	["snatches up a stick and scrawls furiously in the ashes, as if it were a stub of chalk."] = "agarra una rama y garabatea con furia en la ceniza, como si fuera un cabito de gis.",
	["sneezes enormously, then looks around in horror."] = "suelta un estornudo descomunal y luego mira alrededor con horror.",
	["sniffs one wrist, winces, and wipes it on their knee."] = "se huele una muñeca, hace una mueca y se la limpia en la rodilla.",
	["sniffs the air once, then stops, and presses their lips together."] = "olfatea el aire una vez, luego se detiene y aprieta los labios.",
	["sniffs the air, then slowly turns their head to look behind them."] = "olfatea el aire y luego voltea la cabeza despacio para mirar hacia atrás.",
	["spreads both hands, palms up, and lifts them slowly."] = "extiende las dos manos con las palmas hacia arriba y las alza despacio.",
	["spreads their arms wide and hisses, then looks faintly embarrassed."] = "abre los brazos de par en par y sisea, y luego pone cara de vergüenza.",
	["spreads their arms wide and wobbles, trying to keep their balance."] = "abre los brazos y se tambalea, tratando de no perder el equilibrio.",
	["spreads their hands in a gesture of complete and final innocence."] = "abre las manos en un gesto de inocencia total y definitiva.",
	["spreads their hands wider and wider apart, as if measuring a raptor that keeps growing."] = "separa las manos cada vez más, como si midiera un raptor que no deja de crecer.",
	["spreads their hands wider and wider, then slowly draws them back into their lap."] = "separa las manos cada vez más, y luego las regresa despacio al regazo.",
	["spreads their hands, still honestly troubled by the question."] = "abre las manos, aún con verdadero desconcierto ante la pregunta.",
	["squares their shoulders and raises one arm, as if a shield still hung from it."] = "cuadra los hombros y alza un brazo, como si todavía le colgara un escudo.",
	["squints across the fire at {target}, tilting their head one way and then the other."] = "entrecierra los ojos mirando a {target} al otro lado del fuego, ladeando la cabeza hacia un lado y luego hacia el otro.",
	["squints along the rim of an invisible mug, deeply unconvinced."] = "mira a lo largo del borde de un tarro invisible, con cero convencimiento.",
	["squints and rubs their temples with both hands."] = "entrecierra los ojos y se frota las sienes con ambas manos.",
	["squints at the coals with a smith's eye, plainly unimpressed, then grins."] = "entrecierra los ojos ante las brasas con mirada de herrero, sin pizca de admiración, y luego sonríe.",
	["stares at nothing in particular for a while before speaking."] = "se queda mirando a la nada un rato antes de hablar.",
	["stares blankly ahead, imitating a whole room of unamused faces."] = "mira al frente sin expresión, imitando a todo un salón de caras serias.",
	["stares down at an invisible bowl, a spoon halfway to their mouth."] = "mira fijamente un plato invisible, con la cuchara a medio camino de la boca.",
	["stares hard into the dark beyond the fire, without blinking."] = "mira fijamente la oscuridad más allá del fuego, sin parpadear.",
	["stares into the coals for a long moment."] = "se queda mirando las brasas un largo rato.",
	["stares into the fire a while before looking up again."] = "se queda mirando el fuego un rato antes de volver a alzar la vista.",
	["stares into the fire, as if it might have an answer of its own."] = "mira fijamente el fuego, como si pudiera tener su propia respuesta.",
	["stares into the flames and doesn't blink for a while."] = "mira fijamente las llamas y no parpadea en un buen rato.",
	["stares into the sullen, smoking fire, and takes their time before going on."] = "mira fijo el fuego hosco y humeante, y se toma su tiempo antes de seguir.",
	["stays very still, head cocked toward the dark, as though for two soft notes."] = "permanece inmóvil, con la cabeza ladeada hacia la oscuridad, como esperando dos notas suaves.",
	["steps their hands forward through the air, one flat palm after the other, testing each one."] = "va adelantando las manos por el aire, una palma plana tras otra, tanteando cada paso.",
	["stirs an invisible pot with growing effort, then stops, the spoon stuck fast."] = "revuelve una olla invisible cada vez con más esfuerzo, y luego se detiene, con la cuchara atascada.",
	["stirs the coals with a stick, lips still moving."] = "remueve las brasas con un palo, todavía moviendo los labios.",
	["stops fiddling with a small gear and just holds it."] = "deja de juguetear con un engrane pequeño y solo lo sostiene.",
	["stops moving entirely, barely breathing, eyes fixed on the dark."] = "deja de moverse por completo, apenas respirando, con los ojos fijos en la oscuridad.",
	["stops talking and holds very still for a moment."] = "deja de hablar y se queda inmóvil un momento.",
	["stops talking and looks just past {target}'s shoulder."] = "deja de hablar y mira justo por encima del hombro de {target}.",
	["straightens their back, chin high, one hand flat over the heart."] = "endereza la espalda, con la barbilla en alto y una mano sobre el corazón.",
	["straightens their collar and attempts an expression of great respectability."] = "se endereza el cuello de la ropa e intenta poner cara de gran respetabilidad.",
	["straightens their own collar, then straightens it again, more carefully."] = "se acomoda el cuello de la ropa, y luego se lo vuelve a acomodar, con más cuidado.",
	["stretches and settles back, ready for sleep."] = "se estira y se acomoda para dormir.",
	["stretches their hands toward a fire, then slowly draws them back."] = "acerca las manos a un fuego y luego las retira despacio.",
	["stretches their mouth into a stiff, uncertain grin, then lets it drop."] = "estira la boca en una sonrisa tiesa e insegura, y luego deja que se le borre.",
	["stretches their shoulders and lets out a slow, contented breath."] = "estira los hombros y suelta un suspiro lento y satisfecho.",
	["strikes their hands together sharply, then shields their eyes from a sudden blaze."] = "choca las manos con fuerza y luego se cubre los ojos ante un resplandor repentino.",
	["studies {target} across the fire with a thoughtful frown."] = "estudia a {target} desde el otro lado del fuego, con el ceño fruncido y aire pensativo.",
	["sways a little where they sit, as if to slow music."] = "se mece un poco en su lugar, como al ritmo de una música lenta.",
	["sways gently where they sit, wearing a look of perfect trust."] = "se balancea suavemente en su sitio, con cara de confianza absoluta.",
	["swings an arm wildly at nothing, falling just short, then lets it drop."] = "lanza un manotazo furioso al aire, sin alcanzar nada, y luego deja caer el brazo.",
	["swings an imaginary pick, slowly, then rubs the small of their back with a groan."] = "blande un pico imaginario, despacio, y luego se frota la espalda baja con un quejido.",
	["swings an invisible tool down onto the ground."] = "descarga una herramienta invisible contra el suelo.",
	["swings one arm in a wide loop over their head and lets something fly."] = "hace girar un brazo en un gran círculo sobre la cabeza y lanza algo por los aires.",
	["takes a bite of the apple, chews, and pitches the core into the fire, where it hisses."] = "le da una mordida a la manzana, mastica y arroja el corazón al fuego, donde chisporrotea.",
	["takes a sip from their cup and makes a sour face."] = "toma un sorbo de su taza y hace una mueca agria.",
	["takes a split log from the firewood, knocks twice on it, and listens to the sound."] = "toma un leño partido de la leña, le da dos golpes y escucha cómo suena.",
	["takes a worn, much-folded letter from a pouch and smooths it out."] = "saca de una bolsita una carta gastada, doblada mil veces, y la alisa.",
	["takes off one boot, turns it over, and watches a thin stream of sand patter into the fire."] = "se quita una bota, la voltea y mira cómo un hilito de arena cae repiqueteando en el fuego.",
	["takes out a small stoppered jar and tilts it toward the light."] = "saca un frasquito tapado y lo inclina hacia la luz.",
	["takes something small from a pocket, looks at it, and puts it carefully away again."] = "saca algo pequeño de un bolsillo, lo mira y lo vuelve a guardar con cuidado.",
	["taps a finger against their chin."] = "se da golpecitos en la barbilla con un dedo.",
	["taps a fingernail once against the rim of a cup, then listens."] = "golpea una vez con la uña el borde de una taza, y escucha.",
	["taps a knuckle gently against an invisible stone, and tilts their head as if listening."] = "golpea suavemente con un nudillo una piedra invisible y ladea la cabeza como si escuchara.",
	["taps a slow rhythm on their own knee with both hands, eyes closed."] = "marca un ritmo lento sobre su rodilla con ambas manos, con los ojos cerrados.",
	["taps a small imaginary gavel, then flinches at the sound."] = "da un golpecito con un pequeño mazo imaginario y luego se sobresalta con el ruido.",
	["taps one knuckle against a piece of firewood and listens."] = "golpea un leño con un nudillo y escucha.",
	["taps out a slow rhythm with one finger: long, short, short."] = "marca un ritmo lento con un dedo: largo, corto, corto.",
	["taps the side of their cup to get everyone's attention."] = "da unos golpecitos a la taza para llamar la atención de todos.",
	["taps the side of their cup, slow and even, like someone counting."] = "da golpecitos en el costado de la taza, lentos y parejos, como quien lleva la cuenta.",
	["taps the side of their nose twice."] = "se da dos golpecitos en un lado de la nariz.",
	["taps their chin, thinking, then spreads their hands helplessly."] = "se da golpecitos en la barbilla mientras piensa, y luego abre las manos, sin saber qué decir.",
	["taps twice on something unseen, then quickly pulls their hand away."] = "da dos golpecitos sobre algo invisible y luego retira la mano rápido.",
	["taps two fingers against their chest, where a badge might have hung."] = "se toca el pecho con dos dedos, donde podría haber colgado una insignia.",
	["taps two fingers slowly against their temple."] = "se da unos golpecitos lentos en la sien con dos dedos.",
	["tears a piece of bread in two, looking at it thoughtfully."] = "parte un pedazo de pan en dos y lo mira con aire pensativo.",
	["tears an invisible strip of meat in two and offers half across a fire."] = "parte en dos una tira invisible de carne y ofrece la mitad por encima del fuego.",
	["tests a knot with both hands, then tests it again."] = "prueba un nudo con ambas manos, y luego lo vuelve a probar.",
	["the first thing you'll mine when you're new to the town. What am I?"] = "lo primero que minas cuando recién arrancas. ¿Qué soy?",
	["the gold, and then I'll carry you over the ground. What am I?"] = "hasta juntar el oro, y entonces te voy a llevar. ¿Qué soy?",
	["the whole city asks if they've heard about you. What am I?"] = "en toda la ciudad preguntan por mí a viva voz. ¿Qué soy?",
	["then rise with my help on a borrowed breath. What am I?"] = "y con un aliento prestado, gracias a mí, vuelve. ¿Qué soy?",
	["throws both arms out as if skidding to a stop, and stares down in horror."] = "extiende los dos brazos como si frenara en seco, y mira hacia abajo con horror.",
	["throws both arms up as if in front of a roaring crowd."] = "alza ambos brazos como ante una multitud que ruge.",
	["throws one arm over their face and leans hard into nothing, gritting their teeth."] = "se cubre la cara con un brazo y empuja con fuerza contra la nada, apretando los dientes.",
	["throws themselves sideways with a great splash of both hands."] = "se tira de lado y salpica con las dos manos, como en un gran chapuzón.",
	["throws up their hands and laughs at the fire."] = "alza las manos en señal de rendición y se ríe mirando el fuego.",
	["thumps a fist against their own chest and listens to the sound."] = "se golpea el pecho con el puño y escucha el sonido.",
	["ties a neat knot in a bit of string without looking, then pulls it loose."] = "hace un nudo limpio en un pedazo de cordel sin mirar, y luego lo deshace de un tirón.",
	["ties the knot again, and this time leaves it tied."] = "vuelve a hacer el nudo, y esta vez lo deja hecho.",
	["tilts an invisible cup slowly sideways and watches it with great suspicion."] = "inclina despacio de lado una taza invisible y la observa con muchísima sospecha.",
	["tilts slowly to one side, holds it for a moment, then straightens with a sigh."] = "se inclina despacio hacia un lado, se sostiene así un momento y luego se endereza con un suspiro.",
	["tilts their face to the sky with their eyes closed and their palms up."] = "alza la cara al cielo con los ojos cerrados y las palmas hacia arriba.",
	["tilts their head and leans it against the empty air, as though resting one ear on something huge."] = "ladea la cabeza y la recarga en el aire vacío, como si apoyara una oreja en algo enorme.",
	["tilts their head back and stares at the sky."] = "echa la cabeza hacia atrás y se queda mirando el cielo.",
	["tilts their head back, as though looking up into tall branches."] = "echa la cabeza hacia atrás, como si mirara unas ramas muy altas.",
	["tilts their head sideways and clears their throat with exaggerated courtesy."] = "ladea la cabeza y carraspea con una cortesía exagerada.",
	["tilts their head sideways and tugs gently at nothing, with growing concern."] = "ladea la cabeza y tira suavemente de la nada, con creciente preocupación.",
	["tilts their head slightly, as though hearing something faint."] = "ladea un poco la cabeza, como si oyera algo muy tenue.",
	["tilts their head toward the dark and attempts an innocent expression."] = "ladea la cabeza hacia la oscuridad e intenta poner cara de inocencia.",
	["tilts their head toward the ground and listens, not moving at all."] = "inclina la cabeza hacia el suelo y escucha, sin moverse en absoluto.",
	["tilts their head, as though listening for rain on a roof far from here."] = "ladea la cabeza, como si escuchara la lluvia sobre un techo muy lejos de aquí.",
	["tilts their head, listening, and holds up one finger for silence."] = "ladea la cabeza, escuchando, y levanta un dedo para pedir silencio.",
	["tilts their head, wearing a look of gentle confusion."] = "ladea la cabeza, con cara de leve desconcierto.",
	["tips a little from their waterskin onto the ground beside them, and says nothing more."] = "vierte un poco de su odre en el suelo, a su lado, y no dice nada más.",
	["tips an imaginary hat toward the darkness."] = "saluda a la oscuridad inclinando un sombrero imaginario.",
	["tips their head back and goes quiet, gazing straight up."] = "echa la cabeza hacia atrás y se queda en silencio, mirando hacia arriba.",
	["tosses a dry twig into the flames and watches how quickly it is gone."] = "arroja una ramita seca a las llamas y mira lo rápido que desaparece.",
	["tosses a small bone into the fire with great bitterness."] = "arroja un huesito al fuego con gran amargura.",
	["tosses an apple up and catches it without looking."] = "lanza una manzana al aire y la atrapa sin mirar.",
	["touches one finger to an imaginary jug and frosts it with tremendous solemnity."] = "toca una jarra imaginaria con un dedo y la escarcha con una solemnidad tremenda.",
	["touches their rolled bedding, then draws their hands back toward the warmth."] = "toca su petate enrollado y luego retira las manos hacia el calor.",
	["touches two fingers to the ground, then to their heart."] = "se toca el suelo con dos dedos y luego el corazón.",
	["traces a few letters in the dirt with one finger, then wipes them away."] = "traza unas letras en la tierra con un dedo y luego las borra.",
	["traces a few slow letters in the air with one finger."] = "traza despacio unas cuantas letras en el aire con un dedo.",
	["traces a line across an invisible page, lips moving silently."] = "recorre con el dedo un renglón de una página invisible, moviendo los labios sin voz.",
	["traces a line across their palm with one finger, then taps it with a knuckle."] = "traza una línea en su palma con un dedo, y luego le da un golpecito con el nudillo.",
	["traces a little patch shape in the air and goes still."] = "dibuja en el aire la forma de un pequeño parche y deja de moverse.",
	["traces a long, winding shape across the sky with one finger."] = "traza con un dedo en el cielo una forma larga y serpenteante.",
	["tucks something small into an invisible crack, glancing left and right."] = "mete algo pequeñito en una grieta invisible, mirando a un lado y a otro.",
	["tucks the cord away and looks out past the firelight."] = "guarda el cordel y mira más allá de la luz del fuego.",
	["tucks the folded paper into a pocket, close to their heart."] = "guarda el papel doblado en un bolsillo, cerca del corazón.",
	["tucks the invisible button into a pocket and pats it."] = "guarda el botón invisible en un bolsillo y le da una palmadita.",
	["tucks the jar away again, gently, and pats the pocket twice."] = "vuelve a guardar el frasco, con cuidado, y le da dos palmaditas al bolsillo.",
	["tucks their elbows in tight and works both hands in a small space, feeling for something."] = "pega los codos al cuerpo y mueve las dos manos en un espacio pequeño, buscando algo a tientas.",
	["tugs at a lead rope, then lets it go slack."] = "jala de un cabestro y luego lo deja flojo.",
	["tugs at their sleeve and checks the stitching, as if for the hundredth time."] = "jala la manga y revisa las costuras, como por centésima vez.",
	["turns a cup slowly in their hands, not drinking."] = "le da vueltas despacio a una taza entre las manos, sin beber.",
	["turns a flat stone over in their fingers, as if looking for water to skip it on."] = "le da vueltas entre los dedos a una piedra plana, como si buscara agua donde hacerla rebotar.",
	["turns a folded paper over in their hands without opening it."] = "le da vueltas en las manos a un papel doblado sin abrirlo.",
	["turns a pebble over and sets it down without a sound."] = "le da vuelta a un guijarro y lo deja en el suelo sin hacer ruido.",
	["turns a small stone in their fingers, looking over at {target}."] = "le da vueltas a una piedrita entre los dedos, mirando a {target}.",
	["turns a small, invisible package over in their hands."] = "le da vueltas en las manos a un paquetito invisible.",
	["turns a smooth gray pebble over in their fingers."] = "le da vueltas entre los dedos a una piedrita gris y lisa.",
	["turns a stick over in the coals and does not look up."] = "le da vuelta a una rama entre las brasas y no levanta la vista.",
	["turns an invisible knot over in their fingers, slowly, examining it."] = "le da vueltas a un nudo invisible entre los dedos, despacio, examinándolo.",
	["turns an invisible page, slowly, and runs a finger down it."] = "pasa despacio una página invisible y recorre la hoja con un dedo.",
	["turns an invisible page, slowly, then stops and does not turn the next one."] = "pasa despacio una página invisible, luego se detiene y no pasa la siguiente.",
	["turns invisible pages, slowly, one at a time."] = "pasa páginas invisibles, despacio, una por una.",
	["turns one hand over slowly, as if holding something small and bright."] = "voltea una mano despacio, como si sostuviera algo pequeño y brillante.",
	["turns one hand over slowly, palm down, and lays it flat."] = "voltea una mano despacio, con la palma hacia abajo, y la deja plana.",
	["turns one hand palm up, then palm down, and stares at it."] = "pone una mano con la palma hacia arriba, luego hacia abajo, y se la queda mirando.",
	["turns one open hand toward the other, leaving a little space between them."] = "vuelve una mano abierta hacia la otra, dejando un poco de espacio entre ellas.",
	["turns one palm over and studies it for a while."] = "voltea una palma hacia arriba y se la queda mirando un buen rato.",
	["turns one palm upward as though weighing a leaf, then closes their fingers."] = "pone una palma hacia arriba como si pesara una hoja, y luego cierra los dedos.",
	["turns out one empty pocket, then the other, and sighs."] = "voltea un bolsillo vacío, luego el otro, y suspira.",
	["turns over something small on the ground with one finger, and watches it crawl away."] = "voltea con un dedo algo pequeñito en el suelo, y lo mira irse arrastrando.",
	["turns partway from the fire, then stops and glances back over one shoulder into the dark."] = "se aparta un poco del fuego, luego se detiene y mira por encima del hombro hacia la oscuridad.",
	["turns the blade so the firelight slides along its edge, and looks at it for a while."] = "gira la hoja para que la luz del fuego se deslice por el filo, y la mira un buen rato.",
	["turns the invisible letter around and holds it out so the writing faces {target}."] = "voltea la carta invisible y la extiende para que lo escrito quede frente a {target}.",
	["turns the wood to the firelight, then takes off another curl and flicks it into the flames."] = "gira la madera hacia la luz del fuego, le saca otra viruta y la tira a las llamas.",
	["turns their face away and hunches their shoulders against a blast of wind."] = "voltea la cara y encoge los hombros contra una ráfaga de viento.",
	["turns their face beyond the firelight and pauses as though an answer is still owed."] = "voltea la cara más allá de la luz del fuego y se detiene, como si todavía faltara una respuesta.",
	["turns their face up, as if into a strong wind, and speaks a few silent words."] = "alza la cara, como hacia un viento fuerte, y pronuncia unas cuantas palabras en silencio.",
	["turns their head by slow degrees until they're looking over one shoulder."] = "gira la cabeza poco a poco hasta quedar mirando por encima del hombro.",
	["turns their head to the side and stares with one unblinking eye."] = "gira la cabeza de lado y mira fijamente con un solo ojo, sin parpadear.",
	["turns their head toward the empty air beside them, and holds very still."] = "voltea la cabeza hacia el aire vacío a su lado, y no mueve ni un músculo.",
	["turns to {target} and opens one hand, palm up."] = "se vuelve hacia {target} y abre una mano, con la palma hacia arriba.",
	["turns to {target}, speaking more softly now."] = "se vuelve hacia {target} y ahora habla más bajito.",
	["twirls one finger in a tight little circle, then points sharply."] = "gira un dedo en un circulito apretado, y luego apunta de golpe.",
	["twists an invisible handful of grass together and ties it off with care."] = "retuerce un puñado invisible de hierba y lo anuda con cuidado.",
	["twists one fist slowly, as if turning a stiff post in the ground."] = "gira despacio un puño, como si torciera un poste duro clavado en la tierra.",
	["twists their whole body and yanks hard on a strap."] = "retuerce todo el cuerpo y jala con fuerza una correa.",
	["twitches their nose and jerks their head around, wide-eyed, at nothing."] = "frunce la nariz y voltea la cabeza de golpe, con los ojos muy abiertos, hacia la nada.",
	["unfolds a scrap of paper and holds it up for all to admire."] = "desdobla un pedazo de papel y lo levanta para que todos lo admiren.",
	["unfolds an invisible stool with great pride and pats the top of it."] = "despliega un banquito invisible con enorme orgullo y le da palmaditas al asiento.",
	["unrolls a map and smooths it flat with both hands."] = "desenrolla un mapa y lo alisa con las dos manos.",
	["wags a finger across the fire at {target}."] = "le menea un dedo a {target} por encima del fuego, a modo de advertencia.",
	["waits while a log settles in the fire with a low thud, and does not seem to like the sound."] = "espera a que un leño se acomode en el fuego con un golpe sordo, y no parece gustarle el sonido.",
	["walks two fingers briskly off the edge of one knee, then winces all the way down."] = "hace caminar dos dedos a toda prisa hasta el borde de una rodilla, y hace una mueca durante toda la caída.",
	["watches a log settle in the fire and does not look up for a moment."] = "mira cómo se acomoda un leño en el fuego y por un momento no levanta la vista.",
	["watches a log settle in the fire and does not speak again."] = "mira cómo se acomoda un leño en el fuego y no vuelve a hablar.",
	["watches a slow ripple of heat cross the coals, and lets it fade."] = "observa una lenta onda de calor que cruza las brasas, y deja que se apague.",
	["watches one spark circle up above the flames, around and around, until it winks out."] = "sigue con la vista una chispa que sube en círculos sobre las llamas, vuelta y vuelta, hasta que se apaga.",
	["watches something roll slowly past, following it with one pointing finger."] = "mira algo que pasa rodando despacio, siguiéndolo con el dedo.",
	["watches the fire for a while, the way one might watch a lit window from outside."] = "mira el fuego un rato, como quien mira desde afuera una ventana iluminada.",
	["watches the smoke climb as it might from a chimney, and is the first to look away."] = "mira subir el humo como si saliera de una chimenea, y es quien primero aparta la vista.",
	["watches the smoke drift off into the dark for a long while."] = "mira cómo el humo se pierde en la oscuridad durante un largo rato.",
	["watches the smoke drift toward the listeners, scowls, and waves it back."] = "mira cómo el humo se va hacia los que escuchan, frunce el ceño y lo espanta de vuelta con la mano.",
	["watches the smoke lean one way, then the other, and nods as if it had spoken."] = "observa cómo el humo se inclina hacia un lado y luego hacia el otro, y asiente como si le hubiera hablado.",
	["watches the space behind {target} for a long, slow moment, then looks back to the flames."] = "observa un largo rato el espacio detrás de {target}, sin prisa, y luego vuelve a mirar las llamas.",
	["watches the sparks climb until the last one goes out."] = "mira las chispas subir hasta que se apaga la última.",
	["watches the sparks go up into the dark and lets the moment hang."] = "mira cómo suben las chispas en la oscuridad y deja que el momento se alargue.",
	["watches the sparks lift off the fire and drift away into the dark, one by one."] = "mira cómo las chispas se elevan del fuego y se pierden en la oscuridad, una por una.",
	["watches which way the smoke leans, and does not remark on it."] = "observa hacia dónde se inclina el humo, y no comenta nada.",
	["waves a hand in front of their face and coughs politely."] = "agita una mano frente a la cara y tose con educación.",
	["waves a hand in front of their nose."] = "se abanica la nariz con la mano.",
	["weighs the seed over the flames for a moment, then closes their fingers around it and puts it away."] = "sostiene la semilla sobre las llamas un momento, como si la pesara, y luego cierra los dedos sobre ella y la guarda.",
	["wets a finger, holds it up, and slowly turns to face the other way."] = "se moja un dedo, lo alza y se da la vuelta despacio hacia el otro lado.",
	["whips an invisible rope around something twice and leans back hard with both hands."] = "enrolla dos veces una cuerda invisible alrededor de algo y se echa hacia atrás con fuerza, con ambas manos.",
	["wiggles two fingers at the fire, and the flames happen to give a small, weary dance."] = "menea dos dedos hacia el fuego, y da la casualidad de que las llamas bailan un poquito, sin ganas.",
	["winces at the memory, then laughs quietly to themselves."] = "hace una mueca al recordarlo y luego se ríe bajito para sus adentros.",
	["winds up and throws something hard and high, then holds very still, watching."] = "toma impulso y lanza algo con fuerza y bien alto, y luego no mueve ni un músculo, mirando.",
	["wipes the last circle out of the ashes with one fingertip."] = "borra el último círculo de la ceniza con la punta de un dedo.",
	["wipes their hands slowly on their knees, as if they can't quite get them clean."] = "se limpia las manos despacio en las rodillas, como si no lograra dejarlas limpias.",
	["wraps both hands around their cup with one thumb hooked over the rim, and looks at it."] = "rodea la taza con las dos manos, con un pulgar enganchado en el borde, y la mira.",
	["wraps one hand slowly around the other."] = "envuelve despacio una mano con la otra.",
	["wrenches an invisible rail free with both hands and drives it forward and down."] = "arranca con ambas manos un travesaño invisible y lo clava hacia adelante y hacia abajo.",
	["wrings out the end of their sleeve and looks at it without hope."] = "exprime la punta de la manga y la mira sin ninguna esperanza.",
	["wrings out the hem of one sleeve, laughing."] = "exprime el borde de una manga entre risas.",
	["wrinkles their nose and holds an invisible shard at arm's length."] = "arruga la nariz y sostiene un fragmento invisible con el brazo bien estirado.",
	["wrinkles their nose and leans slowly away from their own armpit."] = "arruga la nariz y se aleja despacio de su propia axila.",
	["writes a line of small, tidy letters in the ashes with a stick, and leaves the last word unfinished."] = "escribe con un palito una línea de letras pequeñas y pulcras en la ceniza, y deja la última palabra sin terminar.",
	["yanks an invisible strap twice, then lets it go with a sigh."] = "jala dos veces una correa invisible y luego la suelta con un suspiro.",
	["yanks one hand sharply backward, then stares at the empty space in front of them."] = "jala una mano bruscamente hacia atrás y luego se queda mirando el espacio vacío de enfrente.",
	["yet hold me and wait, and I'll bring you back home. What am I?"] = "pero tenme en la mano y espera, y te llevo al lugar elegido. ¿Qué soy?",
	["your bags"] = "tu bolsa",
	["{target}, I should warn you. People have been talking."] = "{target}, tengo que advertirte. La gente anda hablando.",
	["{target}, an old friend and I have argued for years over whether soup is a food or a drink. We've ruined a lot of good soup over it."] = "{target}, una vieja amiga y yo llevamos años discutiendo si la sopa es comida o bebida. Hemos arruinado mucha sopa buena por eso.",
	["{target}, would you mind if I told you something about where you're sitting? It's nothing bad. Probably."] = "{target}, ¿te molesta si te cuento algo sobre el lugar donde te sentaste? No es nada malo. Seguramente.",
	["{target}, you seem sensible, so I'll tell you what I tell everyone who eats at my fire."] = "{target}, pareces una persona sensata, así que te voy a decir lo que le digo a todo el que come en mi fogata.",
})
